// ============================================================================
// COMPLETE WEIGHTED COMPARISON ENGINE - ALL MODULES EMBEDDED
// Single file containing: Amortization + Scenarios + Selector + Balloon + Aggregator + Renderer
// ============================================================================

// ============================================================================
// MODULE 1: AMORTIZATION ENGINE
// ============================================================================

/**
 * Generate amortization schedule for a loan/balloon finance scenario
 */
function generateAmortizationSchedule(principal, months, apr, balloonAmount = 0) {
  const monthlyRate = apr / 12;
  const schedule = [];
  let balance = principal;
  
  for (let month = 1; month <= months; month++) {
    const interest = balance * monthlyRate;
    let principalPayment;
    let payment;
    
    if (month === months && balloonAmount > 0) {
      // Last payment: include balloon
      principalPayment = balance - balloonAmount;
      payment = principalPayment + interest + balloonAmount;
      balance = 0;
    } else {
      // Standard amortization
      if (monthlyRate > 0) {
        const factor = Math.pow(1 + monthlyRate, months - month + 1);
        const denominator = Math.pow(1 + monthlyRate, months) - 1;
        payment = (principal * monthlyRate * factor) / denominator;
      } else {
        payment = principal / months;
      }
      
      principalPayment = payment - interest;
      balance = Math.max(0, balance - principalPayment);
    }
    
    schedule.push({
      month,
      payment: Math.round(payment * 100) / 100,
      principal: Math.round(principalPayment * 100) / 100,
      interest: Math.round(interest * 100) / 100,
      balance: Math.round(balance * 100) / 100
    });
  }
  
  return schedule;
}

/**
 * Generate lease payment schedule
 */
function generateLeaseSchedule(capCost, residual, months, moneyFactor, monthlyTax = 0) {
  const monthlyDepreciation = (capCost - residual) / months;
  const rentCharge = (capCost + residual) * moneyFactor;
  const schedule = [];
  
  for (let month = 1; month <= months; month++) {
    const payment = monthlyDepreciation + rentCharge + monthlyTax;
    
    schedule.push({
      month,
      payment: Math.round(payment * 100) / 100,
      depreciation: Math.round(monthlyDepreciation * 100) / 100,
      rent: Math.round(rentCharge * 100) / 100,
      tax: Math.round(monthlyTax * 100) / 100,
      balance: Math.round((capCost - (monthlyDepreciation * month)) * 100) / 100
    });
  }
  
  return schedule;
}

/**
 * Min-max normalization: convert all metrics to 0-100 scale (inverted for cost)
 */
function normalizeAndScore(scenarios, weights = { monthly: 0.33, totalCost: 0.33, costPerMile: 0.33 }) {
  if (!scenarios || scenarios.length === 0) return [];
  
  // Find min/max for each metric
  const ranges = {
    monthly: {
      min: Math.min(...scenarios.map(s => s.metrics?.monthly || s.monthly || 0)),
      max: Math.max(...scenarios.map(s => s.metrics?.monthly || s.monthly || 0))
    },
    totalCost: {
      min: Math.min(...scenarios.map(s => s.metrics?.totalCost || s.totalCost || 0)),
      max: Math.max(...scenarios.map(s => s.metrics?.totalCost || s.totalCost || 0))
    },
    costPerMile: {
      min: Math.min(...scenarios.map(s => s.metrics?.costPerMile || s.costPerMile || 0)),
      max: Math.max(...scenarios.map(s => s.metrics?.costPerMile || s.costPerMile || 0))
    }
  };
  
  // Normalize and score each scenario
  return scenarios.map(scenario => {
    const monthly = scenario.metrics?.monthly || scenario.monthly || 0;
    const totalCost = scenario.metrics?.totalCost || scenario.totalCost || 0;
    const costPerMile = scenario.metrics?.costPerMile || scenario.costPerMile || 0;
    
    // Normalize: lower cost = higher score (inverted)
    const normMonthly = ranges.monthly.max > ranges.monthly.min
      ? (1 - (monthly - ranges.monthly.min) / (ranges.monthly.max - ranges.monthly.min)) * 100
      : 50;
    
    const normTotal = ranges.totalCost.max > ranges.totalCost.min
      ? (1 - (totalCost - ranges.totalCost.min) / (ranges.totalCost.max - ranges.totalCost.min)) * 100
      : 50;
    
    const normMile = ranges.costPerMile.max > ranges.costPerMile.min
      ? (1 - (costPerMile - ranges.costPerMile.min) / (ranges.costPerMile.max - ranges.costPerMile.min)) * 100
      : 50;
    
    // Weighted score
    const weightedScore = (normMonthly * weights.monthly) + (normTotal * weights.totalCost) + (normMile * weights.costPerMile);
    
    return {
      ...scenario,
      normalized: { monthly: normMonthly, totalCost: normTotal, costPerMile: normMile },
      weightedScore: Math.round(weightedScore * 10) / 10
    };
  });
}

// Weight presets
const WEIGHT_PRESETS = {
  equal: {
    name: 'Equal (All 3 Equally)',
    weights: { monthly: 0.33, totalCost: 0.33, costPerMile: 0.33 }
  },
  costFocused: {
    name: 'Cost Focused (Total Cost Priority)',
    weights: { monthly: 0.25, totalCost: 0.50, costPerMile: 0.25 }
  },
  paymentFocused: {
    name: 'Payment Focused (Monthly Priority)',
    weights: { monthly: 0.50, totalCost: 0.25, costPerMile: 0.25 }
  },
  balanced: {
    name: 'Balanced',
    weights: { monthly: 0.35, totalCost: 0.40, costPerMile: 0.25 }
  }
};

// ============================================================================
// MODULE 2: SCENARIO BUILDER
// ============================================================================

/**
 * Build all 12 scenarios for a single vehicle card
 */
function buildAllScenariosForCard(card, vehicleIndex = 1) {
  const capCost = getNum(card.querySelector('.capAmount'));
  const residual = getNum(card.querySelector('.residualValue'));
  const sellingPrice = getNum(card.querySelector('.sellingPrice'));
  const leaseTerm = parseInt(card.querySelector('.leaseTerm').value);
  const apr = getNum(card.querySelector('.apr')) / 100;
  const mf = getNum(card.querySelector('.moneyFactor'));
  const annualMiles = parseInt(card.querySelector('.annualMileage').value);
  const downPayment = getNum(card.querySelector('.downPayment'));
  const taxRate = getNum(card.querySelector('.taxRate')) / 100;
  const totalFees = getNum(card.querySelector('.totalFees')) || 0;
  
  const make = card.querySelector('.make')?.value || 'Vehicle';
  const model = card.querySelector('.model')?.value || '';
  const year = card.querySelector('.year')?.value || '';
  
  const vehicleLabel = `${year} ${make} ${model}`.trim();
  const totalMiles = annualMiles * (leaseTerm / 12);
  const taxPerMonth = (capCost / leaseTerm) * taxRate;
  
  const scenarios = [];
  
  // 1. LEASE
  const leaseSchedule = generateLeaseSchedule(capCost, residual, leaseTerm, mf, taxPerMonth);
  const leaseMonthly = leaseSchedule[0]?.payment || 0;
  const leaseTotal = leaseSchedule.reduce((sum, row) => sum + row.payment, 0) + downPayment + totalFees;
  scenarios.push({
    id: `v${vehicleIndex}_lease`,
    label: `${vehicleLabel} – Lease (${leaseTerm}mo/${annualMiles}k)`,
    scenario: 'lease',
    termMonths: leaseTerm,
    metrics: {
      monthly: leaseMonthly,
      totalCost: leaseTotal,
      costPerMile: totalMiles > 0 ? leaseTotal / totalMiles : 0,
      dueAtSigning: downPayment
    },
    schedule: leaseSchedule
  });
  
  // 2. FINANCE
  const financeSchedule = generateAmortizationSchedule(sellingPrice - downPayment, leaseTerm, apr, 0);
  const financeMonthly = financeSchedule[0]?.payment || 0;
  const financeTotal = financeSchedule.reduce((sum, row) => sum + row.payment, 0) + downPayment + (sellingPrice * taxRate) + totalFees;
  scenarios.push({
    id: `v${vehicleIndex}_finance`,
    label: `${vehicleLabel} – Finance (${leaseTerm}mo)`,
    scenario: 'finance',
    termMonths: leaseTerm,
    metrics: {
      monthly: financeMonthly,
      totalCost: financeTotal,
      costPerMile: totalMiles > 0 ? financeTotal / totalMiles : 0,
      dueAtSigning: downPayment
    },
    schedule: financeSchedule
  });
  
  // 3. LEASE + BUY (36+24)
  const buyoutTerm = 24;
  const buyoutSchedule = generateAmortizationSchedule(residual, buyoutTerm, apr * 0.95, 0); // 95% APR for buyout
  const leaseAndBuyMonthly = (leaseTotal + buyoutSchedule.reduce((sum, row) => sum + row.payment, 0)) / (leaseTerm + buyoutTerm);
  const leaseAndBuyTotal = leaseTotal + buyoutSchedule.reduce((sum, row) => sum + row.payment, 0);
  const leaseAndBuyMiles = annualMiles * ((leaseTerm + buyoutTerm) / 12);
  scenarios.push({
    id: `v${vehicleIndex}_lease_buy`,
    label: `${vehicleLabel} – Lease + Buy (${leaseTerm}mo + ${buyoutTerm}mo)`,
    scenario: 'lease_buy',
    termMonths: leaseTerm + buyoutTerm,
    metrics: {
      monthly: leaseAndBuyMonthly,
      totalCost: leaseAndBuyTotal,
      costPerMile: leaseAndBuyMiles > 0 ? leaseAndBuyTotal / leaseAndBuyMiles : 0,
      dueAtSigning: downPayment,
      residualBuyout: residual
    },
    schedule: [...leaseSchedule, ...buyoutSchedule]
  });
  
  // 4. BALLOON LEASE (50% deferred)
  const balloonDepreciation = (capCost - residual) * 0.5;
  const balloonLeaseMonthly = (balloonDepreciation / leaseTerm) + (capCost + residual) * mf + taxPerMonth;
  const balloonLeaseTotal = (balloonLeaseMonthly * leaseTerm) + balloonDepreciation + downPayment + totalFees;
  scenarios.push({
    id: `v${vehicleIndex}_balloon_lease`,
    label: `${vehicleLabel} – Balloon Lease (${leaseTerm}mo, 50% deferred)`,
    scenario: 'balloon_lease',
    termMonths: leaseTerm,
    metrics: {
      monthly: balloonLeaseMonthly,
      totalCost: balloonLeaseTotal,
      costPerMile: totalMiles > 0 ? balloonLeaseTotal / totalMiles : 0,
      dueAtSigning: downPayment,
      balloonDue: balloonDepreciation
    }
  });
  
  // 5. BALLOON FINANCE
  const balloonAmount = residual;
  const balloonFinanceSchedule = generateAmortizationSchedule(sellingPrice - downPayment, leaseTerm, apr, balloonAmount);
  const balloonFinanceMonthly = balloonFinanceSchedule[0]?.payment || 0;
  const balloonFinanceTotal = balloonFinanceSchedule.reduce((sum, row) => sum + row.payment, 0) + downPayment + (sellingPrice * taxRate) + totalFees;
  scenarios.push({
    id: `v${vehicleIndex}_balloon_finance`,
    label: `${vehicleLabel} – Balloon Finance (${leaseTerm}mo)`,
    scenario: 'balloon_finance',
    termMonths: leaseTerm,
    metrics: {
      monthly: balloonFinanceMonthly,
      totalCost: balloonFinanceTotal,
      costPerMile: totalMiles > 0 ? balloonFinanceTotal / totalMiles : 0,
      dueAtSigning: downPayment,
      balloonDue: balloonAmount
    },
    schedule: balloonFinanceSchedule
  });
  
  // 6. SINGLE PAY LEASE (lump sum)
  scenarios.push({
    id: `v${vehicleIndex}_single_pay`,
    label: `${vehicleLabel} – Single Pay Lease (${leaseTerm}mo)`,
    scenario: 'single_pay',
    termMonths: leaseTerm,
    metrics: {
      monthly: leaseTotal / leaseTerm,
      totalCost: leaseTotal,
      costPerMile: totalMiles > 0 ? leaseTotal / totalMiles : 0,
      dueAtSigning: leaseTotal
    }
  });
  
  // 7-12. SUBVENTED (subsidized rate) variants
  const subMf = mf * 0.70; // 30% subsidy
  const subLeaseSchedule = generateLeaseSchedule(capCost, residual, leaseTerm, subMf, taxPerMonth);
  const subLeaseMonthly = subLeaseSchedule[0]?.payment || 0;
  const subLeaseTotal = subLeaseSchedule.reduce((sum, row) => sum + row.payment, 0) + downPayment + totalFees;
  
  scenarios.push({
    id: `v${vehicleIndex}_subvented`,
    label: `${vehicleLabel} – Subvented Lease (${leaseTerm}mo)`,
    scenario: 'subvented',
    termMonths: leaseTerm,
    metrics: {
      monthly: subLeaseMonthly,
      totalCost: subLeaseTotal,
      costPerMile: totalMiles > 0 ? subLeaseTotal / totalMiles : 0,
      dueAtSigning: downPayment
    },
    schedule: subLeaseSchedule
  });
  
  // 8. SUBVENTED + BUY
  const subLeaseAndBuyTotal = subLeaseTotal + buyoutSchedule.reduce((sum, row) => sum + row.payment, 0);
  const subLeaseAndBuyMonthly = subLeaseAndBuyTotal / (leaseTerm + buyoutTerm);
  scenarios.push({
    id: `v${vehicleIndex}_subvented_buy`,
    label: `${vehicleLabel} – Subvented + Buy (${leaseTerm}mo + ${buyoutTerm}mo)`,
    scenario: 'subvented_buy',
    termMonths: leaseTerm + buyoutTerm,
    metrics: {
      monthly: subLeaseAndBuyMonthly,
      totalCost: subLeaseAndBuyTotal,
      costPerMile: leaseAndBuyMiles > 0 ? subLeaseAndBuyTotal / leaseAndBuyMiles : 0,
      dueAtSigning: downPayment,
      residualBuyout: residual
    }
  });
  
  // 9. SUBVENTED SINGLE PAY
  scenarios.push({
    id: `v${vehicleIndex}_subvented_single`,
    label: `${vehicleLabel} – Subvented Single Pay (${leaseTerm}mo)`,
    scenario: 'subvented_single',
    termMonths: leaseTerm,
    metrics: {
      monthly: subLeaseTotal / leaseTerm,
      totalCost: subLeaseTotal,
      costPerMile: totalMiles > 0 ? subLeaseTotal / totalMiles : 0,
      dueAtSigning: subLeaseTotal
    }
  });
  
  // 10-12. Additional variants for completeness
  scenarios.push({
    id: `v${vehicleIndex}_balloon_lease_buy`,
    label: `${vehicleLabel} – Balloon Lease + Buy (${leaseTerm}mo + ${buyoutTerm}mo)`,
    scenario: 'balloon_lease_buy',
    termMonths: leaseTerm + buyoutTerm,
    metrics: {
      monthly: (balloonLeaseTotal + buyoutSchedule.reduce((sum, row) => sum + row.payment, 0)) / (leaseTerm + buyoutTerm),
      totalCost: balloonLeaseTotal + buyoutSchedule.reduce((sum, row) => sum + row.payment, 0),
      costPerMile: leaseAndBuyMiles > 0 ? (balloonLeaseTotal + buyoutSchedule.reduce((sum, row) => sum + row.payment, 0)) / leaseAndBuyMiles : 0,
      dueAtSigning: downPayment
    }
  });
  
  // Remaining 2 scenarios as variants
  scenarios.push({
    id: `v${vehicleIndex}_finance_short`,
    label: `${vehicleLabel} – Finance Short Term (24mo)`,
    scenario: 'finance_short',
    termMonths: 24,
    metrics: {
      monthly: (sellingPrice - downPayment) / 24,
      totalCost: sellingPrice + (sellingPrice * taxRate) + totalFees,
      costPerMile: ((annualMiles * 2) > 0) ? (sellingPrice + (sellingPrice * taxRate) + totalFees) / (annualMiles * 2) : 0,
      dueAtSigning: downPayment
    }
  });
  
  scenarios.push({
    id: `v${vehicleIndex}_lease_extended`,
    label: `${vehicleLabel} – Extended Lease (48mo)`,
    scenario: 'lease_extended',
    termMonths: 48,
    metrics: {
      monthly: leaseMonthly * 0.85, // Slightly lower over longer term
      totalCost: (leaseMonthly * 0.85 * 48) + downPayment + totalFees,
      costPerMile: ((annualMiles * 4) > 0) ? ((leaseMonthly * 0.85 * 48) + downPayment + totalFees) / (annualMiles * 4) : 0,
      dueAtSigning: downPayment
    }
  });
  
  return scenarios;
}

/**
 * Build and score all scenarios for all vehicles
 */
function buildAndScoreAllScenarios(cards, weightPreset = 'equal') {
  const allScenarios = [];
  
  cards.forEach((card, idx) => {
    const scenarios = buildAllScenariosForCard(card, idx + 1);
    allScenarios.push(...scenarios);
  });
  
  const weights = WEIGHT_PRESETS[weightPreset]?.weights || WEIGHT_PRESETS.equal.weights;
  const scored = normalizeAndScore(allScenarios, weights);
  scored.sort((a, b) => b.weightedScore - a.weightedScore);
  
  return { allScenarios: scored, weights };
}

// ============================================================================
// MODULE 3: SCENARIO SELECTOR
// ============================================================================

function addScenarioSelector(card, scenarios) {
  const vehicleIndex = card.dataset.vehicleIndex;
  
  let selectorSection = card.querySelector('.scenario-selector-section');
  if (!selectorSection) {
    selectorSection = document.createElement('div');
    selectorSection.className = 'scenario-selector-section';
    selectorSection.style.cssText = `
      background: #e0f2fe; border: 2px solid #0369a1; border-radius: 8px;
      padding: 15px; margin-bottom: 15px;
    `;
    
    const cardHeader = card.querySelector('.card-header');
    if (cardHeader) {
      cardHeader.parentNode.insertBefore(selectorSection, cardHeader.nextSibling);
    } else {
      card.insertBefore(selectorSection, card.querySelector('.section'));
    }
  }
  
  let html = `<div style="margin-bottom: 10px;">
    <label style="display: block; font-weight: 700; font-size: 0.85rem; margin-bottom: 6px; color: #0369a1;">
      📊 Select Scenario for Comparison
    </label>
    <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 6px;">`;
  
  scenarios.forEach((scenario, idx) => {
    const isFirst = idx === 0;
    const shortLabel = scenario.label.replace(/^[^–]*–/, '').replace(/\([^)]*\)/g, '').trim().substring(0, 18);
    
    html += `<button 
      class="scenario-btn ${isFirst ? 'active' : ''}"
      data-vehicle-index="${vehicleIndex}"
      data-scenario-id="${scenario.id}"
      onclick="selectScenarioForCard(this)"
      title="${scenario.label}"
      style="padding: 8px 10px; border: 2px solid #0369a1; background: ${isFirst ? '#0369a1' : 'white'};
        color: ${isFirst ? 'white' : '#0369a1'}; border-radius: 6px; font-size: 0.7rem;
        font-weight: 700; cursor: pointer; transition: all 0.2s;"
    >${shortLabel}</button>`;
  });
  
  html += `</div></div>
    <div style="font-size: 0.75rem; color: #0369a1; margin-top: 8px; font-style: italic;">
      Selected: <span class="scenario-selection-display">Loading...</span>
    </div>`;
  
  selectorSection.innerHTML = html;
  card.dataset.allScenarios = JSON.stringify(scenarios);
  card.dataset.selectedScenarioId = scenarios[0]?.id;
  updateScenarioDisplay(card, scenarios[0]);
}

function selectScenarioForCard(btn) {
  const vehicleIndex = btn.dataset.vehicleIndex;
  const scenarioId = btn.dataset.scenarioId;
  const card = document.querySelector(`[data-vehicle-index="${vehicleIndex}"]`);
  
  if (!card) return;
  
  const allBtns = card.querySelectorAll('.scenario-btn');
  allBtns.forEach(b => {
    if (b.dataset.scenarioId === scenarioId) {
      b.classList.add('active');
      b.style.background = '#0369a1';
      b.style.color = 'white';
    } else {
      b.classList.remove('active');
      b.style.background = 'white';
      b.style.color = '#0369a1';
    }
  });
  
  card.dataset.selectedScenarioId = scenarioId;
  const allScenarios = JSON.parse(card.dataset.allScenarios);
  const selectedScenario = allScenarios.find(s => s.id === scenarioId);
  updateScenarioDisplay(card, selectedScenario);
  updateComparisonTable();
}

function updateScenarioDisplay(card, scenario) {
  const display = card.querySelector('.scenario-selection-display');
  if (display && scenario) {
    const shortLabel = scenario.label.replace(/^[^–]*–/, '').trim();
    display.textContent = shortLabel;
  }
}

function getSelectedScenarios() {
  const cards = document.querySelectorAll('.vehicle-card');
  const selected = [];
  
  cards.forEach((card, idx) => {
    const vehicleIndex = card.dataset.vehicleIndex;
    const selectedScenarioId = card.dataset.selectedScenarioId;
    
    if (!selectedScenarioId) return;
    
    try {
      const allScenarios = JSON.parse(card.dataset.allScenarios);
      const scenario = allScenarios.find(s => s.id === selectedScenarioId);
      
      if (scenario) {
        scenario.vehicleNumber = vehicleIndex;
        selected.push(scenario);
      }
    } catch (e) {
      console.error(`Error parsing scenarios for vehicle ${vehicleIndex}:`, e);
    }
  });
  
  return selected;
}

function initializeScenarioSelectors() {
  const cards = document.querySelectorAll('.vehicle-card');
  
  cards.forEach((card, idx) => {
    const vehicleIndex = idx + 1;
    card.dataset.vehicleIndex = vehicleIndex;
    const scenarios = buildAllScenariosForCard(card, vehicleIndex);
    addScenarioSelector(card, scenarios);
  });
}

function updateComparisonTable() {
  const selectedScenarios = getSelectedScenarios();
  
  if (selectedScenarios.length === 0) {
    showToast('Select at least one scenario', 'error');
    return;
  }
  
  const weights = getCurrentWeights ? getCurrentWeights() : WEIGHT_PRESETS.equal.weights;
  const scored = normalizeAndScore(selectedScenarios, weights);
  scored.sort((a, b) => b.weightedScore - a.weightedScore);
  
  renderWeightedScorecard({ allScenarios: scored, weights });
  document.getElementById('comparisonSection').classList.remove('hidden');
}

// ============================================================================
// MODULE 4: BALLOON RESTRUCTURE ENGINE
// ============================================================================

function calculateBalloonRemaining(capCost, residualValue, termMonths, balloonMonthsElapsed) {
  const totalDepreciation = capCost - residualValue;
  const monthlyDepreciation = totalDepreciation / termMonths;
  const totalDepreciationSoFar = monthlyDepreciation * balloonMonthsElapsed;
  const remainingToBalloon = totalDepreciation - totalDepreciationSoFar;
  
  return {
    monthlyDepreciation,
    totalDepreciationSoFar,
    remainingToBalloon,
    balloonCapRemaining: capCost - totalDepreciationSoFar
  };
}

// ============================================================================
// MODULE 5: COMPARISON AGGREGATOR
// ============================================================================

function aggregateCardCalculations(card) {
  const vehicleIndex = card.dataset.vehicleIndex;
  
  const make = card.querySelector('.make')?.value || '';
  const model = card.querySelector('.model')?.value || '';
  const year = card.querySelector('.year')?.value || '';
  
  const msrp = getNum(card.querySelector('.msrp'));
  const sellingPrice = getNum(card.querySelector('.sellingPrice'));
  const capAmount = getNum(card.querySelector('.capAmount')) || msrp;
  const residualValue = getNum(card.querySelector('.residualValue'));
  const apr = getNum(card.querySelector('.apr')) / 100 || 0.05;
  const moneyFactor = getNum(card.querySelector('.moneyFactor'));
  const leaseTerm = parseInt(card.querySelector('.leaseTerm').value);
  const annualMiles = parseInt(card.querySelector('.annualMileage').value);
  const downPayment = getNum(card.querySelector('.downPayment'));
  const taxRate = getNum(card.querySelector('.taxRate')) / 100;
  
  return {
    vehicleIndex,
    vehicleInfo: {
      year,
      make,
      model,
      displayName: `${year} ${make} ${model}`
    },
    inputs: {
      msrp,
      sellingPrice,
      capAmount,
      residualValue,
      apr: apr * 100,
      moneyFactor,
      leaseTerm,
      annualMiles,
      downPayment,
      taxRate: taxRate * 100
    },
    derived: {
      totalMiles: annualMiles * (leaseTerm / 12),
      depreciationAmount: capAmount - residualValue
    }
  };
}

function buildComparisonOutput(card, selectedScenarioId) {
  let allScenarios = [];
  try {
    allScenarios = JSON.parse(card.dataset.allScenarios || '[]');
  } catch (e) {
    console.error('Error parsing scenarios:', e);
    return null;
  }
  
  const selectedScenario = allScenarios.find(s => s.id === selectedScenarioId);
  if (!selectedScenario) return null;
  
  const cardCalcs = aggregateCardCalculations(card);
  
  return {
    id: selectedScenario.id,
    vehicleIndex: cardCalcs.vehicleIndex,
    vehicleInfo: cardCalcs.vehicleInfo,
    scenario: selectedScenario.scenario,
    label: selectedScenario.label,
    inputs: cardCalcs.inputs,
    calculations: {
      monthly: selectedScenario.metrics.monthly,
      totalCost: selectedScenario.metrics.totalCost,
      costPerMile: selectedScenario.metrics.costPerMile,
      dueAtSigning: selectedScenario.metrics.dueAtSigning
    },
    metrics: {
      monthly: selectedScenario.metrics.monthly,
      totalCost: selectedScenario.metrics.totalCost,
      costPerMile: selectedScenario.metrics.costPerMile
    }
  };
}

function getAllComparisonOutputs() {
  const cards = document.querySelectorAll('.vehicle-card');
  const outputs = [];
  
  cards.forEach((card) => {
    const selectedScenarioId = card.dataset.selectedScenarioId;
    if (!selectedScenarioId) return;
    
    const output = buildComparisonOutput(card, selectedScenarioId);
    if (output) outputs.push(output);
  });
  
  return outputs;
}

// ============================================================================
// MODULE 6: COMPARISON RENDERER
// ============================================================================

function renderWeightedScorecard(bundle) {
  const { allScenarios, weights } = bundle;
  const table = document.getElementById('comparisonTableLease');
  
  if (!table || !allScenarios || allScenarios.length === 0) return;
  
  let html = `<thead><tr><th>Metric</th>`;
  
  allScenarios.forEach(scenario => {
    html += `<th>${scenario.vehicleInfo?.displayName || scenario.label}<br/><small>${scenario.scenario}</small></th>`;
  });
  
  html += `</tr></thead><tbody>`;
  
  // Monthly Payment Row
  html += `<tr><td><strong>Monthly</strong></td>`;
  const monthlyValues = allScenarios.map(s => s.metrics?.monthly || 0);
  const maxMonthly = Math.max(...monthlyValues);
  const minMonthly = Math.min(...monthlyValues);
  
  allScenarios.forEach(scenario => {
    const val = scenario.metrics?.monthly || 0;
    const isBest = Math.abs(val - minMonthly) < 0.01;
    const isWorst = Math.abs(val - maxMonthly) < 0.01;
    const arrow = isBest ? '▲' : isWorst ? '▼' : '▶';
    const color = isBest ? 'green' : isWorst ? 'red' : 'orange';
    
    html += `<td style="color: ${color}; font-weight: 700;">$${Math.round(val).toLocaleString()} ${arrow}</td>`;
  });
  html += `</tr>`;
  
  // Total Cost Row
  html += `<tr><td><strong>Total Cost</strong></td>`;
  const totalValues = allScenarios.map(s => s.metrics?.totalCost || 0);
  const maxTotal = Math.max(...totalValues);
  const minTotal = Math.min(...totalValues);
  
  allScenarios.forEach(scenario => {
    const val = scenario.metrics?.totalCost || 0;
    const isBest = Math.abs(val - minTotal) < 1;
    const isWorst = Math.abs(val - maxTotal) < 1;
    const arrow = isBest ? '▲' : isWorst ? '▼' : '▶';
    const color = isBest ? 'green' : isWorst ? 'red' : 'orange';
    
    html += `<td style="color: ${color}; font-weight: 700;">$${Math.round(val).toLocaleString()} ${arrow}</td>`;
  });
  html += `</tr>`;
  
  // Cost Per Mile Row
  html += `<tr><td><strong>Cost/Mile</strong></td>`;
  const mileValues = allScenarios.map(s => s.metrics?.costPerMile || 0);
  const maxMile = Math.max(...mileValues);
  const minMile = Math.min(...mileValues);
  
  allScenarios.forEach(scenario => {
    const val = scenario.metrics?.costPerMile || 0;
    const isBest = Math.abs(val - minMile) < 0.01;
    const isWorst = Math.abs(val - maxMile) < 0.01;
    const arrow = isBest ? '▲' : isWorst ? '▼' : '▶';
    const color = isBest ? 'green' : isWorst ? 'red' : 'orange';
    
    html += `<td style="color: ${color}; font-weight: 700;">$${val.toFixed(2)} ${arrow}</td>`;
  });
  html += `</tr>`;
  
  // Weighted Score & Ranking
  html += `<tr style="background: #f0f0f0; font-weight: 700;"><td><strong>Weighted Score</strong></td>`;
  allScenarios.forEach((scenario, idx) => {
    const medal = idx === 0 ? '🥇' : idx === 1 ? '🥈' : idx === 2 ? '🥉' : (idx + 1);
    html += `<td>${scenario.weightedScore?.toFixed(1) || 0} ${medal}</td>`;
  });
  html += `</tr>`;
  
  html += `</tbody>`;
  table.innerHTML = html;
}

function renderWeightSelector(containerId, onChangeCallback) {
  const container = document.getElementById(containerId);
  if (!container) return;
  
  container.innerHTML = `
    <div style="padding: 15px; background: #f9fafb; border-radius: 8px; margin-bottom: 15px;">
      <h3 style="margin-top: 0;">Weight Controls (Equal Default)</h3>
      <div style="display: grid; gap: 12px;">
        <div>
          <label>Monthly Payment: <span id="wMonthlyValue">33%</span></label>
          <input type="range" id="wMonthly" min="0" max="100" value="33" 
            style="width: 100%;" onchange="autoNormalizeWeights(); ${onChangeCallback ? onChangeCallback.name ? onChangeCallback.name + '()' : '' : ''}">
        </div>
        <div>
          <label>Total Cost: <span id="wTotalValue">33%</span></label>
          <input type="range" id="wTotal" min="0" max="100" value="33" 
            style="width: 100%;" onchange="autoNormalizeWeights(); ${onChangeCallback ? onChangeCallback.name ? onChangeCallback.name + '()' : '' : ''}">
        </div>
        <div>
          <label>Cost Per Mile: <span id="wMileValue">34%</span></label>
          <input type="range" id="wMile" min="0" max="100" value="34" 
            style="width: 100%;" onchange="autoNormalizeWeights(); ${onChangeCallback ? onChangeCallback.name ? onChangeCallback.name + '()' : '' : ''}">
        </div>
      </div>
    </div>
  `;
}

function autoNormalizeWeights() {
  const m = parseInt(document.getElementById('wMonthly')?.value || 33);
  const t = parseInt(document.getElementById('wTotal')?.value || 33);
  const mi = parseInt(document.getElementById('wMile')?.value || 34);
  const total = m + t + mi;
  
  if (total !== 100) {
    document.getElementById('wMile').value = 100 - m - t;
  }
  
  document.getElementById('wMonthlyValue').textContent = m + '%';
  document.getElementById('wTotalValue').textContent = t + '%';
  document.getElementById('wMileValue').textContent = (100 - m - t) + '%';
}

function getCurrentWeights() {
  const m = parseInt(document.getElementById('wMonthly')?.value || 33);
  const t = parseInt(document.getElementById('wTotal')?.value || 33);
  const mi = parseInt(document.getElementById('wMile')?.value || 34);
  const total = m + t + mi;
  
  return {
    monthly: m / total,
    totalCost: t / total,
    costPerMile: mi / total
  };
}

