document.addEventListener('DOMContentLoaded', function() {
    // Only add one vehicle on page load
    if (vehicles.length === 0) {
        addVehicle();
    }
});

// 
// ADD VEHICLE
// 

function addVehicle() {
    if (vehicles.length >= 6) {
        showToast('Maximum 6 vehicles allowed');
        return;
    }
    
    vehicleCounter++;
    
    const vehicle = {
        id: `vehicle-${vehicleCounter}`,
        data: {}
    };
    
    vehicles.push(vehicle);
    
    const template = document.getElementById('vehicleTemplate');
    const clone = template.content.cloneNode(true);
    const card = clone.querySelector('.vehicle-card');
    card.dataset.vehicleId = vehicle.id;
    
    const header = card.querySelector('.vehicle-header h2');
    header.textContent = `Vehicle ${vehicles.length}`;
    
    document.getElementById('vehiclesContainer').appendChild(clone);
    updateVehicleCounter();
    
    // Set up event listeners
    setupVehicleListeners(document.querySelector(`[data-vehicle-id="${vehicle.id}"]`));
    
    showToast(`Vehicle ${vehicles.length} added`);
}

function setupVehicleListeners(card) {
    // VIN decode
    const vinInput = card.querySelector('.vin');
    if (vinInput) {
        vinInput.addEventListener('blur', function() {
            if (this.value.length === 17) {
                decodeVIN(this.value, card);
            }
        });
    }
    
    // ZIP decode
    const zipInput = card.querySelector('.zipCode');
    if (zipInput) {
        zipInput.addEventListener('blur', function() {
            if (this.value.length === 5) {
                decodeZIP(this.value, card);
            }
        });
    }
    
    // Fuel type change
    const fuelTypeSelect = card.querySelector('.fuelType');
    if (fuelTypeSelect) {
        fuelTypeSelect.addEventListener('change', function() {
            updateFuelFieldVisibility(card, this.value);
        });
        // Trigger on load
        updateFuelFieldVisibility(card, fuelTypeSelect.value);
    }
    
    // Auto-calculate fields
    card.addEventListener('input', function(e) {
        if (e.target.classList.contains('annualMileage') || 
            e.target.classList.contains('epaCombinedMpg') ||
            e.target.classList.contains('fuelCostPerGallon')) {
            calculateGasFuelCost(card);
        }
        
        if (e.target.classList.contains('annualMileage') || 
            e.target.classList.contains('mpgeCombined') ||
            e.target.classList.contains('l2ChargingRate')) {
            calculateEVEnergyCost(card);
        }
    });
}

// 
// FUEL TYPE VISIBILITY
// 

function updateFuelFieldVisibility(card, fuelType) {
    const gasSection = card.querySelector('.gas-field');
    const evSection = card.querySelector('.ev-field');
    const phevSection = card.querySelector('.phev-field');
    
    if (gasSection) gasSection.style.display = (fuelType === 'Gasoline') ? 'block' : 'none';
    if (evSection) evSection.style.display = (fuelType === 'Electric (EV)') ? 'block' : 'none';
    if (phevSection) phevSection.style.display = (fuelType === 'Plug-in Hybrid (PHEV)') ? 'block' : 'none';
}

// 
// VIN DECODE
// 

function decodeVIN(vin, card) {
    console.log('Decoding VIN:', vin);
    
    // Step 1: Try NEOVIN
    const neovinKey = 'YOUR_NEOVIN_KEY';
    
    fetch(`https://api.neovin.com/v1/vin/${vin}?key=${neovinKey}`)
        .then(response => response.json())
        .then(data => {
            if (data && data.success) {
                console.log('NEOVIN data:', data);
                populateVehicleData(data, card, 'neovin');
                
                // Get EPA data as supplement
                fetchEPAData(data.year, data.make, data.model, card);
            } else {
                // Fallback to NHTSA
                decodeVINNHTSA(vin, card);
            }
        })
        .catch(err => {
            console.error('NEOVIN failed:', err);
            decodeVINNHTSA(vin, card);
        });
    
    // Also fetch listing data
    fetchListingData(vin, card);
}

function decodeVINNHTSA(vin, card) {
    console.log('Using NHTSA decode');
    
    fetch(`https://vpic.nhtsa.dot.gov/api/vehicles/DecodeVinValues/${vin}?format=json`)
        .then(response => response.json())
        .then(data => {
            if (data.Results && data.Results.length > 0) {
                console.log('NHTSA data:', data.Results[0]);
                populateVehicleData(data.Results[0], card, 'nhtsa');
                
                const year = data.Results[0].ModelYear;
                const make = data.Results[0].Make;
                const model = data.Results[0].Model;
                
                if (year && make && model) {
                    fetchEPAData(year, make, model, card);
                }
            }
        })
        .catch(err => console.error('NHTSA decode failed:', err));
}

function fetchEPAData(year, make, model, card) {
    if (!window.EPA_DATA) {
        console.log('EPA_DATA not loaded');
        return;
    }
    
    const epaVehicle = EPA_DATA.find(v => 
        v.year == year && 
        v.make.toLowerCase() === make.toLowerCase() &&
        v.model.toLowerCase().includes(model.toLowerCase())
    );
    
    if (epaVehicle) {
        console.log('Found EPA data:', epaVehicle);
        populateEPAData(epaVehicle, card);
    }
}

function populateVehicleData(data, card, source) {
    // Year
    const yearField = card.querySelector('.year');
    if (yearField && !yearField.value) {
        yearField.value = source === 'neovin' ? data.year : data.ModelYear;
    }
    
    // Make
    const makeField = card.querySelector('.make');
    if (makeField && !makeField.value) {
        makeField.value = data.make || data.Make;
    }
    
    // Model
    const modelField = card.querySelector('.model');
    if (modelField && !modelField.value) {
        modelField.value = data.model || data.Model;
    }
    
    // Trim
    const trimField = card.querySelector('.trim');
    if (trimField && !trimField.value) {
        const trim = source === 'neovin' ? data.trim : data.Trim;
        if (trim) trimField.value = trim;
    }
    
    // Exterior Color
    const exteriorColorField = card.querySelector('.exteriorColor');
    if (exteriorColorField && data.exterior_color) {
        exteriorColorField.value = data.exterior_color;
    }
    
    // Interior Color
    const interiorColorField = card.querySelector('.interiorColor');
    if (interiorColorField && data.interior_color) {
        interiorColorField.value = data.interior_color;
    }
    
    // Fuel Type
    const fuelTypeField = card.querySelector('.fuelType');
    if (fuelTypeField && data.fuel_type) {
        fuelTypeField.value = data.fuel_type;
        updateFuelFieldVisibility(card, data.fuel_type);
    }
}

function populateEPAData(epaData, card) {
    // Detect fuel type
    let fuelType = 'Gasoline';
    if (epaData.fuelType1 && epaData.fuelType1.includes('Electric')) {
        fuelType = 'Electric (EV)';
    } else if (epaData.atvType && epaData.atvType.includes('Plug-in')) {
        fuelType = 'Plug-in Hybrid (PHEV)';
    }
    
    const fuelTypeField = card.querySelector('.fuelType');
    if (fuelTypeField) {
        fuelTypeField.value = fuelType;
        updateFuelFieldVisibility(card, fuelType);
    }
    
    // Gasoline fields
    if (fuelType === 'Gasoline') {
        setFieldValue(card, '.epaCityMpg', epaData.city08 || epaData.cityMPG);
        setFieldValue(card, '.epaHwyMpg', epaData.highway08 || epaData.highwayMPG);
        setFieldValue(card, '.epaCombinedMpg', epaData.comb08 || epaData.combinedMPG);
        setFieldValue(card, '.fuelTankSize', epaData.fuelTankGallons || epaData.tankSize);
        
        const range = (epaData.comb08 || epaData.combinedMPG) * (epaData.fuelTankGallons || epaData.tankSize || 0);
        setFieldValue(card, '.gasRange', Math.round(range));
        
        calculateGasFuelCost(card);
    }
    
    // EV fields
    if (fuelType === 'Electric (EV)') {
        setFieldValue(card, '.mpgeCity', epaData.cityMPGe || epaData.city08);
        setFieldValue(card, '.mpgeHighway', epaData.highwayMPGe || epaData.highway08);
        setFieldValue(card, '.mpgeCombined', epaData.combinedMPGe || epaData.comb08);
        setFieldValue(card, '.batterySize', epaData.batteryCapacity || epaData.kwhBattery);
        setFieldValue(card, '.electricRange', epaData.range || epaData.electricRange);
        
        calculateEVEnergyCost(card);
    }
    
    // PHEV fields
    if (fuelType === 'Plug-in Hybrid (PHEV)') {
        setFieldValue(card, '.mpgeCityElectric', epaData.cityMPGe || epaData.city08);
        setFieldValue(card, '.mpgeHighwayElectric', epaData.highwayMPGe || epaData.highway08);
        setFieldValue(card, '.mpgeCombinedElectric', epaData.combinedMPGe || epaData.comb08);
        setFieldValue(card, '.electricRange', epaData.range || epaData.electricRange);
        setFieldValue(card, '.batterySize', epaData.batteryCapacity || epaData.kwhBattery);
        
        setFieldValue(card, '.mpgCityGas', epaData.cityA08 || epaData.city08Gas);
        setFieldValue(card, '.mpgHighwayGas', epaData.highwayA08 || epaData.highway08Gas);
        setFieldValue(card, '.mpgCombinedGas', epaData.combA08 || epaData.comb08Gas);
        setFieldValue(card, '.fuelTankSize', epaData.fuelTankGallons || epaData.tankSize);
        
        const gasRange = (epaData.combA08 || epaData.comb08Gas || 0) * (epaData.fuelTankGallons || epaData.tankSize || 0);
        setFieldValue(card, '.gasRange', Math.round(gasRange));
        
        const totalRange = (epaData.range || epaData.electricRange || 0) + gasRange;
        setFieldValue(card, '.totalRange', Math.round(totalRange));
        
        calculatePHEVEnergyCost(card);
    }
}

function setFieldValue(card, selector, value) {
    const field = card.querySelector(selector);
    if (field && value !== undefined && value !== null) {
        field.value = value;
    }
}

// 
// ZIP DECODE
// 

function decodeZIP(zip, card) {
    console.log('Decoding ZIP:', zip);
    
    fetch(`https://api.zippopotam.us/us/${zip}`)
        .then(response => response.json())
        .then(data => {
            console.log('ZIP data:', data);
            
            if (data.places && data.places.length > 0) {
                const place = data.places[0];
                
                // City
                const cityField = card.querySelector('.city');
                if (cityField) cityField.value = place['place name'];
                
                // County
                const countyField = card.querySelector('.county');
                if (countyField) countyField.value = place['county'] || '';
                
                // State
                const stateField = card.querySelector('.state');
                const stateAbbr = place['state abbreviation'];
                if (stateField) stateField.value = stateAbbr;
                
                // Tax Rate
                const taxRateField = card.querySelector('.taxRate');
                if (taxRateField && stateAbbr) {
                    const taxRate = STATE_TAX_RATES[stateAbbr] || 0;
                    taxRateField.value = taxRate;
                }
                
                showToast('ZIP decoded successfully');
            }
        })
        .catch(err => {
            console.error('ZIP decode failed:', err);
            showToast('ZIP decode failed');
        });
}

