// ============================================================================
// SECTION 2: RESIDUAL LOOKUP ENHANCED (from residual_lookup_enhanced.js)
// ============================================================================
/**

RESIDUAL LOOKUP ENHANCED

5-tier confidence hierarchy for accurate residual/MF values
*/

let SCRAPED_DATA = null;

/**

Initialize - Load scraped data
*/
async function initializeScrapedData() {
try {
const response = await fetch('/data/scraped_manufacturer_financial_data.json');
if (!response.ok) throw new Error('Failed to load');

 SCRAPED_DATA = await response.json();
 console.log('✓ Scraped data loaded. Records:', SCRAPED_DATA.metadata.totalRecordsAnalyzed);
 return true;

} catch (error) {
console.warn('⚠ Could not load scraped data:', error);
SCRAPED_DATA = null;
return false;
}
}

/**

TIER 1: Aggregated Data (90% confidence)
*/
function getResidualFromAggregated(make, model, term, mileage) {
if (!SCRAPED_DATA?.manufacturers) return null;

const makeKey = make.toLowerCase();
const modelKey = model.toLowerCase();

const makeData = SCRAPED_DATA.manufacturers[makeKey];
if (!makeData?.models) return null;

const modelData = makeData.models[modelKey];
if (!modelData || modelData.confidence < 0.85) return null;

let residual = modelData.residualAverage || 0;
residual = applyTermAdjustment(residual, term);
residual = applyMileageAdjustment(residual, mileage);

return {
residual: residual,
confidence: 0.90,
source: 'aggregated',
dataPoints: modelData.count,
tier: 1
};
}

/**

TIER 2: Manufacturer Average (75% confidence)
*/
function getResidualFromManufacturer(make, term, mileage) {
if (!SCRAPED_DATA?.manufacturers) return null;

const makeKey = make.toLowerCase();
const makeData = SCRAPED_DATA.manufacturers[makeKey];

if (!makeData?.aggregated?.residualAverage) return null;

let residual = makeData.aggregated.residualAverage;
residual = applyTermAdjustment(residual, term);
residual = applyMileageAdjustment(residual, mileage);

return {
residual: residual,
confidence: 0.75,
source: 'manufacturer_avg',
dataPoints: 0,
tier: 2
};
}

/**

TIER 3: Fallback by vehicle class (50% confidence)
*/
const FALLBACK_RESIDUALS = {
'luxury': 52,
'economy': 45,
'truck': 42,
'suv': 48,
'hybrid': 55,
'ev': 50,
'default': 50
};

function getResidualFromFallback(vehicleClass, term, mileage) {
const fallback = FALLBACK_RESIDUALS[vehicleClass] || FALLBACK_RESIDUALS['default'];

let residual = fallback;
residual = applyTermAdjustment(residual, term);
residual = applyMileageAdjustment(residual, mileage);

return {
    residual: residual,
    confidence: 0.50,
    source: 'fallback',
    dataPoints: 0,
    tier: 3
};

}

/**

Apply term adjustment

24mo: +3%, 36mo: baseline, 39mo: -2%
*/
function applyTermAdjustment(residual, term) {
if (!term || term === 36) return residual;

const adjustments = {
24: 3,
27: 1,
30: 0,
33: 0,
36: 0,
39: -2,
42: -3,
48: -5
};

const adjustment = adjustments[term] || 0;
return residual + adjustment;
}

/**

Apply mileage adjustment

10K: +2%, 12K: baseline, 15K: -3%
*/
function applyMileageAdjustment(residual, mileagePerYear) {
if (!mileagePerYear || mileagePerYear === 12000) return residual;

if (mileagePerYear <= 10000) return residual + 2;
if (mileagePerYear >= 15000) return residual - 3;

return residual;
}

/**

MAIN LOOKUP - Executes tier hierarchy
*/
function getEnhancedResidual(make, model, term = 36, mileage = 12000, vehicleClass = 'default') {
console.log('Residual lookup: ${make} ${model}');

// Tier 1: Aggregated (90%)
let result = getResidualFromAggregated(make, model, term, mileage);
if (result) {
console.log('Tier 1: ${result.residual.toFixed(1)}%');
return result;
}

// Tier 2: Manufacturer Average (75%)
result = getResidualFromManufacturer(make, term, mileage);
if (result) {
console.log('Tier 2: ${result.residual.toFixed(1)}%');
return result;
}

// Tier 3: Fallback (50%)
result = getResidualFromFallback(vehicleClass, term, mileage);
console.log('Tier 3 (Fallback): ${result.residual.toFixed(1)}%');
return result;
}

/**

Get Money Factor
*/
function getEnhancedMoneyFactor(make, model) {
if (!SCRAPED_DATA?.manufacturers) return null;

const makeKey = make.toLowerCase();
const makeData = SCRAPED_DATA.manufacturers[makeKey];

if (!makeData?.aggregated?.mfAverage) return null;

return makeData.aggregated.mfAverage;
}

/**

Format result for UI
*/
function formatResidualResult(result) {
const confidencePercentage = (result.confidence * 100).toFixed(0);
const confidenceColor = result.confidence >= 0.85 ? 'green' :
result.confidence >= 0.70 ? 'yellow' : 'red';

return {
value: result.residual.toFixed(1),
confidence: confidencePercentage,
confidenceColor: confidenceColor,
source: result.source,
tier: result.tier
};
}

/**

Export for main calculator
*/
window.ResidualLookup = {
initialize: initializeScrapedData,
getResidual: getEnhancedResidual,
getMoneyFactor: getEnhancedMoneyFactor,
formatResult: formatResidualResult
};

