// UTILITY: Format currency
const fmt = (n) => typeof n === 'number' ? '$' + n.toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',') : '--';

// UTILITY: Format percentage
const pct = (n) => typeof n === 'number' ? (n*100).toFixed(2) + '%' : '--';

