// FINANCE CALCULATION


// BALLOON CALCULATION
function calculateBalloon(vehicle) {
  const monthDue = parseInt(vehicle.monthBalloonDue) || 36;
  const restructuredTerm = parseInt(vehicle.restructuredTerm) || 0;
  const balloonApr = parseFloat(vehicle.balloonApr) || 0.035;
  const balloonMf = parseFloat(vehicle.balloonMf) || 0.0005;
  
  // Calculate balloon cap/principal
  const cap = parseFloat(vehicle.capitalizedAmount) || 0;
  const downPayment = parseFloat(vehicle.downPayment) || 0;
  const balloonCap = cap - downPayment;
  
  // Balloon payment calculation (simple interest)
  const balloonPayment = balloonCap * (balloonApr / 12) * monthDue;
  
  // New principal after restructure
  let newPrincipal = balloonCap;
  if (restructuredTerm > 0) {
    const addlDown = parseFloat(vehicle.balloonAddlDown) || 0;
    newPrincipal = balloonCap - addlDown;
  }
  
  return {
    balloonCapPrincipal: balloonCap,
    balloonPayment: balloonPayment,
    balloonNewPrincipal: newPrincipal
  };
}

// FUEL COST CALCULATION
function calculateFuelCost(vehicle) {
  const fuelType = vehicle.fuelType || 'gas';
  const annualMileage = parseInt(vehicle.annualMileage) || 12000;
  
  let costPer100Mi = 0;
  let annualCost = 0;
  let kwhPer100Mi = 0;
  
  if (fuelType === 'gas') {
    const mpg = parseFloat(vehicle.epaCombinedMpg) || (parseFloat(vehicle.epaCityMpg) || 20);
    const fuelCost = parseFloat(vehicle.fuelCostPerGal) || 3.50;
    costPer100Mi = (100 / (mpg || 1)) * fuelCost;
    annualCost = (annualMileage / 100) * costPer100Mi;
  } else if (fuelType === 'ev') {
    const mpge = parseFloat(vehicle.mpgeCombined) || 25;
    const elecCost = parseFloat(vehicle.electricityCostPerkWh) || 0.14;
    kwhPer100Mi = 100 / (mpge || 1);
    costPer100Mi = kwhPer100Mi * elecCost;
    annualCost = (annualMileage / 100) * costPer100Mi;
  } else if (fuelType === 'phev') {
    const gasRange = parseFloat(vehicle.rangePhevGas) || 300;
    const evRange = parseFloat(vehicle.rangePhevEv) || 50;
    const combined = (gasRange + evRange) || 1;
    const gasPercent = gasRange / combined;
    const evPercent = evRange / combined;
    
    const mpg = parseFloat(vehicle.phevFuelCostPerGal) || 3.50;
    const elec = parseFloat(vehicle.phevElectricityCostPerkWh) || 0.14;
    
    const gasCost = (100 / 25) * mpg * gasPercent;
    const evCost = (100 / 25) * elec * evPercent;
    costPer100Mi = gasCost + evCost;
    annualCost = (annualMileage / 100) * costPer100Mi;
    kwhPer100Mi = (100 / 25) * evPercent;
  }
  
  return {
    fuelCostPer100Mi: costPer100Mi,
    kwhPer100Mi: kwhPer100Mi,
    annualFuelCost: annualCost
  };
}

// EQUITY CALCULATION
function calculateEquity(vehicle) {
  const tradeAllowance = parseFloat(vehicle.tradeAllowance) || 0;
  const payoffAmount = parseFloat(vehicle.payoffAmount) || 0;
  const equity = tradeAllowance - payoffAmount;
  
  const scenario = vehicle.tradeScenario || 'cap_reduction';
  const cap = parseFloat(vehicle.capitalizedAmount) || 0;
  const res = parseFloat(vehicle.residualValue) || 0;
  
  let equityApplied = 0;
  if (scenario === 'cap_reduction') {
    equityApplied = equity; // Full to cap cost
  } else if (scenario === 'split_50_50') {
    equityApplied = equity / 2; // 50% to cap, 50% to buyout
  } else if (scenario === 'at_buyout') {
    equityApplied = 0; // Apply after lease ends
  } else if (scenario === 'check_back') {
    equityApplied = 0; // Separate account
  }
  
  return {
    tradeEquity: equity,
    equityApplied: equityApplied,
    adjustedCap: Math.max(0, cap - equityApplied)
  };
}

// MSD DISCOUNT CALCULATION
function calculateMSD(vehicle) {
  const msdActive = vehicle.msdActive === true || vehicle.msdActive === 'on';
  if (!msdActive) return {msdSavings: 0};
  
  const msdCount = parseInt(vehicle.msdCount) || 1;
  const mf = parseFloat(vehicle.moneyFactor) || 0.0005;
  const cap = parseFloat(vehicle.capitalizedAmount) || 0;
  const res = parseFloat(vehicle.residualValue) || 0;
  const term = parseInt(vehicle.leaseTerm) || 36;
  
  // Industry standard: each MSD reduces MF by 0.00004
  const mfReduction = 0.00004 * msdCount;
  
  // Apply minimum floor (typically 0.00001)
  const minFloor = 0.00001;
  const adjustedMF = Math.max(minFloor, mf - mfReduction);
  
  // Calculate savings
  const originalRent = (cap + res) * mf * term;
  const adjustedRent = (cap + res) * adjustedMF * term;
  const mfSavings = originalRent - adjustedRent;
  
  return {
    msdSavings: mfSavings,
    adjustedMF: adjustedMF,
    mfReduction: mfReduction
  };
}

// RESIDUAL AUTO-LOOKUP
function autoResidual(vehicle) {
  const term = parseInt(vehicle.leaseTerm) || 36;
  const mileage = parseInt(vehicle.annualMileage) || 12000;
  const condition = vehicle.condition || 'new';
  const msrp = parseFloat(vehicle.msrp) || 0;
  
  // NOTE: Requires external getResidual function
  const residualPct = typeof getResidual === 'function' ? getResidual(term, mileage, condition) : 0.50;
  const residualValue = msrp * residualPct;
  
  return {
    residualPct: residualPct,
    residualValue: residualValue
  };
}

