window.autoPopulateResidual = function(card) {
  const msrp = parseFloat(card.querySelector('.msrp').value) || 0;
  const term = parseInt(card.querySelector('.leaseTerm').value) || 36;
  const mileage = parseInt(card.querySelector('.annualMileage').value) || 12000;
  const condition = card.querySelector('.condition').value || 'new';
  
  const result = autoResidual({leaseTerm: term, annualMileage: mileage, condition: condition, msrp: msrp});
  
  card.querySelector('.residualPct').value = (result.residualPct * 100).toFixed(1);
  card.querySelector('.residualValue').value = result.residualValue.toFixed(0);
};

// CALCULATE BREAKDOWN FOR CARD
window.calculateCardBreakdown = function(card) {
  const dealType = card.querySelector('.dealType').value;
  
  if (dealType === 'lease' || dealType === 'balloon') {
    const lease = calculateLease({
      leaseTerm: card.querySelector('.leaseTerm').value,
      annualMileage: card.querySelector('.annualMileage').value,
      capitalizedAmount: card.querySelector('.capitalizedAmount').value,
      residualValue: card.querySelector('.residualValue').value,
      moneyFactor: card.querySelector('.moneyFactor').value,
      taxRate: card.querySelector('.taxRate').value,
      taxMethod: card.querySelector('.taxMethod').value,
      acqFee: card.querySelector('.acqFee').value,
      docFee: card.querySelector('.docFee').value,
      downPayment: card.querySelector('.downPayment').value,
      dealArrangement: card.querySelector('.dealArrangement').value
    });
    
    card.querySelector('[data-field="capCost"]').textContent = fmt(lease.capCost);
    card.querySelector('[data-field="residualValueDisplay"]').textContent = fmt(lease.residualValue);
    card.querySelector('[data-field="capToRes"]').textContent = fmt(lease.capToRes);
    card.querySelector('[data-field="mfDisplay"]').textContent = lease.mfDisplay;
    card.querySelector('[data-field="rentMonthly"]').textContent = fmt(lease.rentMonthly);
    card.querySelector('[data-field="rentTotal"]').textContent = fmt(lease.rentTotal);
    card.querySelector('[data-field="depMonthly"]').textContent = fmt(lease.depMonthly);
    card.querySelector('[data-field="depTotal"]').textContent = fmt(lease.depTotal);
    card.querySelector('[data-field="taxMonthly"]').textContent = fmt(lease.taxMonthly);
    card.querySelector('[data-field="taxTotal"]').textContent = fmt(lease.taxTotal);
    card.querySelector('[data-field="totalMonthly"]').textContent = fmt(lease.totalMonthly);
    card.querySelector('[data-field="dueAtSigning"]').textContent = fmt(lease.dueAtSigning);
    card.querySelector('[data-field="totalCost"]').textContent = fmt(lease.totalCost);
    card.querySelector('[data-field="buyout"]').textContent = fmt(lease.buyout);
    card.querySelector('[data-field="costPerMile"]').textContent = fmt(lease.costPerMile);
  }
  
  if (dealType === 'finance') {
    const finance = calculateFinance({
      leaseTerm: card.querySelector('.leaseTerm').value,
      annualMileage: card.querySelector('.annualMileage').value,
      capitalizedAmount: card.querySelector('.capitalizedAmount').value,
      apr: card.querySelector('.apr').value,
      downPayment: card.querySelector('.downPayment').value
    });
    
    card.querySelector('[data-field="finLoanAmount"]').textContent = fmt(finance.finLoanAmount);
    card.querySelector('[data-field="finMonthly"]').textContent = fmt(finance.finMonthly);
    card.querySelector('[data-field="finTotalInterest"]').textContent = fmt(finance.finTotalInterest);
    card.querySelector('[data-field="finTotalPayments"]').textContent = fmt(finance.finTotalPayments);
    card.querySelector('[data-field="finTotalCost"]').textContent = fmt(finance.finTotalCost);
    card.querySelector('[data-field="finCostPerMile"]').textContent = fmt(finance.finCostPerMile);
  }
};

