const MAX_VEHICLES = 6;
let vehicles = [];

function addVehicleCard() {
    if (vehicles.length >= MAX_VEHICLES) {
        showToast(`Maximum ${MAX_VEHICLES} vehicles allowed`, 'error');
        return;
    }

    const index = vehicles.length + 1;
    const vehicleData = {
        id: `vehicle-${index}`,
        index: index,
        vin: '',
        zip: '',
        year: new Date().getFullYear(),
        make: '',
        model: '',
        trim: '',
        msrp: 0,
        sellingPrice: 0,
        capitalizedAmount: 0,
        residualValue: 0,
        residualPct: 0.6,
        moneyFactor: 0.0005,
        apr: 0.05,
        taxRate: 0.07,
        leaseTerm: 36,
        annualMileage: 12000,
        downPayment: 0,
        dealType: 'lease',
        dealArrangement: 'closed_end',
        condition: 'new',
        fuelType: 'gas',
        acqFee: 0,
        docFee: 0
    };

    vehicles.push(vehicleData);
    renderVehicleCard(vehicleData);
    updateVehicleCount();
    showToast(`Vehicle ${index} added`);
}

function updateVehicle(index, field, value) {
    const vehicle = vehicles.find(v => v.index == index);
    if (vehicle) vehicle[field] = value;
}


function calculateAllVehicles() {
    vehicles.forEach(vehicle => {
        const capAmount = parseFloat(vehicle.capitalizedAmount) || parseFloat(vehicle.msrp) || 0;
        const residualValue = capAmount * (parseFloat(vehicle.residualPct) || 0.6);

        vehicle.capitalizedAmount = capAmount;
        vehicle.residualValue = residualValue;

        if (vehicle.dealType === 'lease') {
            const lease = calculateLease({
                leaseTerm: vehicle.leaseTerm,
                annualMileage: vehicle.annualMileage,
                capitalizedAmount: capAmount,
                residualValue: residualValue,
                moneyFactor: vehicle.moneyFactor,
                taxRate: vehicle.taxRate,
                acqFee: vehicle.acqFee,
                downPayment: vehicle.downPayment,
                dealArrangement: vehicle.dealArrangement
            });

            document.getElementById(`monthly-payment-${vehicle.index}`).textContent = fmt(lease.totalMonthly);
            document.getElementById(`total-cost-${vehicle.index}`).textContent = fmt(lease.totalCost);
            document.getElementById(`cost-per-mile-${vehicle.index}`).textContent = '$' + lease.costPerMile.toFixed(2);
            document.getElementById(`due-at-signing-${vehicle.index}`).textContent = fmt(lease.dueAtSigning);
        } else if (vehicle.dealType === 'finance') {
            const finance = calculateFinance({
                leaseTerm: vehicle.leaseTerm,
                annualMileage: vehicle.annualMileage,
                capitalizedAmount: vehicle.sellingPrice || capAmount,
                apr: vehicle.apr,
                downPayment: vehicle.downPayment
            });

            document.getElementById(`monthly-payment-${vehicle.index}`).textContent = fmt(finance.finMonthly);
            document.getElementById(`total-cost-${vehicle.index}`).textContent = fmt(finance.finTotalCost);
            document.getElementById(`cost-per-mile-${vehicle.index}`).textContent = '$' + finance.finCostPerMile.toFixed(2);
            document.getElementById(`due-at-signing-${vehicle.index}`).textContent = fmt(vehicle.downPayment);
        }
    });

    showToast('✓ Calculations complete');
}


function showAdvanced() {
    showToast('Advanced features available in extended version');
}


function switchCardTab(e, tabName) {
    const parent = e.target.closest('.vehicle-card');
    parent.querySelectorAll('.tab-content').forEach(el => el.classList.add('hidden'));
    parent.querySelectorAll('.tabs .tab-btn').forEach(btn => btn.classList.remove('active'));
    document.getElementById(tabName).classList.remove('hidden');
    e.target.classList.add('active');
}

function switchSubTab(e, tabName) {
    document.querySelectorAll('.sub-tab-content').forEach(el => el.classList.add('hidden'));
    e.target.closest('.tabs').querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
    document.getElementById(tabName).classList.remove('hidden');
    e.target.classList.add('active');
}


