// SECTION 21: ENERGY CONSUMPTION & FUEL COST CALCULATIONS
// ============================================================================

function calculateFuelCosts(element) {
    const card = element.closest('.vehicle-card');
    if (!card) return;
    
    const fuelType = card.querySelector('input[name^="fuelType"]:checked')?.value || 'gas';
    const avgGasPrice = parseFloat(card.querySelector('.avgGasPrice')?.value) || 3.00;
    const fuelCapacity = parseFloat(card.querySelector('.fuel_capacity')?.value) || 0;
    const batteryCapacity = parseFloat(card.querySelector('.battery_capacity')?.value) || 0;
    const electricityCost = parseFloat(card.querySelector('.electricityCostPerkWh')?.value) || 0.13;
    
    // Parse MPG/MPGe
    const mpgInput = card.querySelector('.mpg')?.value || '0/0/0';
    const mpgParts = mpgInput.split('/').map(p => parseFloat(p.trim()) || 0);
    const mpgCombined = mpgParts[2] || ((mpgParts[0] * 0.45 + mpgParts[1] * 0.55) || 0);
    
    const mpgeInput = card.querySelector('.mpge')?.value || '0/0/0';
    const mpgeParts = mpgeInput.split('/').map(p => parseFloat(p.trim()) || 0);
    const mpgeCombined = mpgeParts[2] || ((mpgeParts[0] * 0.45 + mpgeParts[1] * 0.55) || 0);
    
    // Gas calculations
    if (fuelType === 'gas' || fuelType === 'hev' || fuelType === 'phev') {
        const avgFillCost = fuelCapacity * avgGasPrice;
        const costPer100Mi = mpgCombined > 0 ? (100 / mpgCombined) * avgGasPrice : 0;
        
        if (card.querySelector('.avg_gas_fill_cost')) {
            card.querySelector('.avg_gas_fill_cost').value = '$' + avgFillCost.toFixed(2);
        }
        if (card.querySelector('.cost_per_100_miles')) {
            card.querySelector('.cost_per_100_miles').value = '$' + costPer100Mi.toFixed(2);
        }
    }
    
    // EV/PHEV calculations
    if (fuelType === 'ev' || fuelType === 'phev') {
        const kwhPer100Mi = mpgeCombined > 0 ? (33.7 / mpgeCombined) * 100 : 0;
        const evCostPer100Mi = (kwhPer100Mi / 100) * electricityCost;
        
        if (card.querySelector('.kwhPer100Mi')) {
            card.querySelector('.kwhPer100Mi').value = kwhPer100Mi.toFixed(2);
        }
        if (card.querySelector('.fuelCostPer100Mi')) {
            card.querySelector('.fuelCostPer100Mi').value = '$' + evCostPer100Mi.toFixed(2);
        }
    }
    
    // Annual fuel cost estimate
    const annualMiles = parseFloat(card.querySelector('.annualMileage')?.value) || 12000;
    let annualFuelCost = 0;
    
    if (fuelType === 'gas' || fuelType === 'hev') {
        annualFuelCost = mpgCombined > 0 ? (annualMiles / mpgCombined) * avgGasPrice : 0;
    } else if (fuelType === 'ev') {
        const kwhPerYear = mpgeCombined > 0 ? (annualMiles / mpgeCombined) * 33.7 : 0;
        annualFuelCost = kwhPerYear * electricityCost;
    } else if (fuelType === 'phev') {
        // Assume 60% electric, 40% gas for PHEV
        const electricMiles = annualMiles * 0.6;
        const gasMiles = annualMiles * 0.4;
        const kwhCost = mpgeCombined > 0 ? (electricMiles / mpgeCombined) * 33.7 * electricityCost : 0;
        const gasCost = mpgCombined > 0 ? (gasMiles / mpgCombined) * avgGasPrice : 0;
        annualFuelCost = kwhCost + gasCost;
    }
    
    if (card.querySelector('.annualFuelCost')) {
        card.querySelector('.annualFuelCost').value = '$' + annualFuelCost.toFixed(2);
    }
}

function handleFuelTypeChange(element) {
    const card = element.closest('.vehicle-card');
    if (!card) return;
    
    const fuelType = element.value;
    
    // Show/hide appropriate fields
    const gasFields = card.querySelectorAll('.gas-stats-row, .gas-field');
    const evFields = card.querySelectorAll('.ev-energy-fields, .ev-field');
    const phevFields = card.querySelectorAll('.phev-field');
    
    gasFields.forEach(f => f.classList.toggle('hidden', fuelType === 'ev'));
    evFields.forEach(f => f.classList.toggle('hidden', fuelType === 'gas' || fuelType === 'hev'));
    phevFields.forEach(f => f.classList.toggle('hidden', fuelType !== 'phev'));
    
    calculateFuelCosts(element);
}

// ============================================================================
// SECTION 12: BALLOON RESTRUCTURE ENGINE
// ============================================================================

function calculateBalloonRestructure(card) {
    const balloonTerm = parseInt(card.querySelector('.balloonTerm')?.value) || 60;
    const balloonMonthDue = parseInt(card.querySelector('.balloonMonthDue')?.value) || 36;
    const sellingPrice = parseFloat(card.querySelector('.sellingPrice')?.value) || 0;
    const downPayment = parseFloat(card.querySelector('.downPayment')?.value) || 0;
    const apr = parseFloat(card.querySelector('.apr')?.value) / 100 || 0;
    const balloonAddDown = parseFloat(card.querySelector('.balloonAddDown')?.value) || 0;
    const balloonNewTerm = parseInt(card.querySelector('.balloonNewTerm')?.value) || 24;
    
    // Calculate remaining balance at balloon due date
    const principal = sellingPrice - downPayment;
    const monthlyRate = apr / 12;
    
    // Amortization for original term
    const originalPayment = monthlyRate > 0 
        ? principal * (monthlyRate * Math.pow(1 + monthlyRate, balloonTerm)) / (Math.pow(1 + monthlyRate, balloonTerm) - 1)
        : principal / balloonTerm;
    
    // Calculate remaining balance at balloon due month
    let remainingBalance = principal;
    for (let i = 0; i < balloonMonthDue; i++) {
        const interestPayment = remainingBalance * monthlyRate;
        const principalPayment = originalPayment - interestPayment;
        remainingBalance -= principalPayment;
    }
    
    // Display remaining balance
    if (card.querySelector('.balloonRemCap')) {
        card.querySelector('.balloonRemCap').value = '$' + remainingBalance.toFixed(2);
    }
    
    // Calculate refinance payment
    const refinanceAmount = remainingBalance - balloonAddDown;
    const refinancePayment = monthlyRate > 0
        ? refinanceAmount * (monthlyRate * Math.pow(1 + monthlyRate, balloonNewTerm)) / (Math.pow(1 + monthlyRate, balloonNewTerm) - 1)
        : refinanceAmount / balloonNewTerm;
    
    if (card.querySelector('.balloonNewPay')) {
        card.querySelector('.balloonNewPay').value = '$' + refinancePayment.toFixed(2);
    }
    
    return {
        originalPayment,
        remainingBalance,
        refinancePayment,
        totalPhase1Cost: originalPayment * balloonMonthDue,
        totalPhase2Cost: refinancePayment * balloonNewTerm,
        totalCost: (originalPayment * balloonMonthDue) + (refinancePayment * balloonNewTerm) + downPayment + balloonAddDown
    };
}

