async function fetchMarketCheckNeoVIN(card) {
    const vin = card.querySelector('.vin')?.value.trim().toUpperCase();
    if (!vin || vin.length !== 17) return;
    
    const loadingIndicator = card.querySelector('.loading-indicator');
    if (loadingIndicator) loadingIndicator.textContent = 'Fetching VIN data...';
    
    try {
        const apiKey = getNextApiKey();
        const res = await fetch(`https://api.marketcheck.com/v2/decode/car/neovin/${vin}/specs?api_key=${apiKey}&include_generic=true`);
        
        if (!res.ok) {
            console.log("MarketCheck failed, falling back to NHTSA");
            fetchNHTSAVIN(card);
            return;
        }
        
        const data = await res.json();
        
        // Basic vehicle info
        card.querySelector('.year').value = data.year || '';
        card.querySelector('.make').value = data.make || '';
        card.querySelector('.model').value = data.model || '';
        card.querySelector('.trim').value = data.trim || '';
        
        // PROTECT MSRP: Only update if API returns > 0
        if (data.msrp && data.msrp > 0) {
            card.querySelector('.msrp').value = data.msrp;
            if (card.querySelector('.origMsrpHidden')) {
                card.querySelector('.origMsrpHidden').value = data.msrp;
            }
            if (card.querySelector('.origMsrpDisplay')) {
                card.querySelector('.origMsrpDisplay').value = data.msrp;
            }
        }
        
        // Color
        const color = data.specs?.exterior_color?.name || data.exterior_color?.name || 'Unknown';
        if (card.querySelector('.color')) {
            card.querySelector('.color').value = color;
        }
        
        // Fuel type detection
        const fType = (data.fuel_type || '').toLowerCase();
        const isEV = fType.includes('electric') && !fType.includes('hybrid');
        const isPHEV = fType.includes('plug-in');
        const isHEV = fType.includes('hybrid') && !fType.includes('plug-in');
        
        const generic = data.generic || {};
        const specs = data.specs || {};
        const extra = data.extra || {};
        
        const parseVal = (v) => parseFloat(String(v).replace(/[^0-9.]/g, '')) || 0;
        
        // Fuel capacity
        let fuelCap = data.fuel_capacity || specs.fuel_tank_capacity || generic['Fuel Tank Capacity'] || extra.fuel_capacity;
        if (card.querySelector('.fuel_capacity')) {
            card.querySelector('.fuel_capacity').value = parseVal(fuelCap);
        }
        
        // Battery capacity
        let batt = data.battery_capacity || specs.battery_capacity || generic['Battery Capacity (kWh)'] || extra.battery_capacity;
        if (!batt && isEV) batt = 75;
        if (card.querySelector('.battery_capacity')) {
            card.querySelector('.battery_capacity').value = parseVal(batt);
        }
        
        // Set fuel type radio buttons
        if (isEV && card.querySelector('.fuelTypeEV')) {
            card.querySelector('.fuelTypeEV').checked = true;
            handleFuelTypeChange(card.querySelector('.fuelTypeEV'));
        } else if (isPHEV && card.querySelector('.fuelTypePHEV')) {
            card.querySelector('.fuelTypePHEV').checked = true;
            handleFuelTypeChange(card.querySelector('.fuelTypePHEV'));
        } else if (isHEV && card.querySelector('.fuelTypeHEV')) {
            card.querySelector('.fuelTypeHEV').checked = true;
            handleFuelTypeChange(card.querySelector('.fuelTypeHEV'));
        }
        
        // MPG/MPGe
        const cityMpg = parseVal(data.city_mpg || specs.city_mpg || generic['EPA City MPG']);
        const hwyMpg = parseVal(data.highway_mpg || specs.highway_mpg || generic['EPA Highway MPG']);
        const combMpg = parseVal(data.combined_mpg || specs.combined_mpg || generic['EPA Combined MPG']) || 
                        (cityMpg && hwyMpg ? (cityMpg * 0.45 + hwyMpg * 0.55) : 0);
        
        if (card.querySelector('.mpg')) {
            card.querySelector('.mpg').value = `${cityMpg} / ${hwyMpg} / ${combMpg.toFixed(1)}`;
        }
        
        if (loadingIndicator) loadingIndicator.textContent = '✓ Data loaded';
        calculateFuelCosts(card.querySelector('.avgGasPrice'));
        
    } catch (err) {
        console.error('MarketCheck API error:', err);
        if (loadingIndicator) loadingIndicator.textContent = 'Error fetching data';
    }
}

async function fetchNHTSAVIN(card) {
    const vin = card.querySelector('.vin')?.value.trim().toUpperCase();
    if (!vin || vin.length !== 17) return;
    
    try {
        const res = await fetch(`https://vpic.nhtsa.dot.gov/api/vehicles/DecodeVin/${vin}?format=json`);
        const data = await res.json();
        
        const results = data.Results || [];
        const getValue = (varName) => results.find(r => r.Variable === varName)?.Value || '';
        
        card.querySelector('.year').value = getValue('Model Year');
        card.querySelector('.make').value = getValue('Make');
        card.querySelector('.model').value = getValue('Model');
        card.querySelector('.trim').value = getValue('Trim');
        
    } catch (err) {
        console.error('NHTSA API error:', err);
    }
}

