async function fetchLocationData(card) {
    const zip = card.querySelector('.zip')?.value.trim();
    if (!zip || zip.length !== 5) return;
    
    try {
        // Get city/state from ZIP
        const res = await fetch(`https://api.zippopotam.us/us/${zip}`);
        const data = await res.json();
        const place = data.places[0];
        const state = place['state abbreviation'];
        
        if (card.querySelector('.city')) {
            card.querySelector('.city').value = place['place name'];
        }
        if (card.querySelector('.state')) {
            card.querySelector('.state').value = state;
        }
        
        // Set tax rate
        const tax = TAX_RATES[state] || 6.00;
        if (card.querySelector('.taxRate')) {
            card.querySelector('.taxRate').value = tax;
        }
        
        // Get county via FCC Geo API
        if (place.latitude && place.longitude) {
            const geoRes = await fetch(
                `https://geo.fcc.gov/api/census/block/find?format=json&latitude=${place.latitude}&longitude=${place.longitude}&showall=true`
            );
            const geoData = await geoRes.json();
            
            if (geoData.County && geoData.County.name && card.querySelector('.county')) {
                card.querySelector('.county').value = geoData.County.name;
            }
        }
        
        // Set state-specific doc fee (you'll need to define this object)
        const DOC_FEE_BY_STATE = {
            'CA': 85, 'FL': 899, 'GA': 499, 'TX': 150, 'NY': 175,
            'DEFAULT': 299
        };
        
        if (card.querySelector('.docFee')) {
            card.querySelector('.docFee').value = DOC_FEE_BY_STATE[state] || DOC_FEE_BY_STATE.DEFAULT;
        }
        
    } catch (err) {
        console.error('Location API error:', err);
    }
}

// ============================================================================
// SECTION 15: PAYMENT SENSITIVITY MATRIX GENERATOR
// ============================================================================

function generateMatrixTable() {
    const vehicleSelect = document.getElementById('matrixTargetVehicle');
    const selectedIndex = parseInt(vehicleSelect.value);
    
    if (isNaN(selectedIndex)) {
        alert('Please select a vehicle to analyze');
        return;
    }
    
    const cards = document.querySelectorAll('.vehicle-card');
    const card = cards[selectedIndex];
    
    const msrp = parseFloat(card.querySelector('.msrp')?.value) || 0;
    const sellingPrice = parseFloat(card.querySelector('.sellingPrice')?.value) || msrp;
    const residualPct = parseFloat(card.querySelector('.residualPct')?.value) || 60;
    const mf = parseFloat(card.querySelector('.moneyFactor')?.value) || 0.00125;
    const taxRate = parseFloat(card.querySelector('.taxRate')?.value) / 100 || 0.07;
    const annualMiles = parseInt(card.querySelector('.annualMileage')?.value) || 12000;
    
    const terms = [24, 27, 30, 33, 36, 39, 42, 45, 48, 60, 72, 84];
    const downPayments = [0, 1000, 2000, 3000, 4000, 5000, 7500, 10000];
    
    let html = '<table class="matrix-table"><thead><tr><th>Term / Down</th>';
    downPayments.forEach(down => {
        html += `<th>$${down.toLocaleString()}</th>`;
    });
    html += '</tr></thead><tbody>';
    
    terms.forEach(term => {
        html += `<tr><td><strong>${term} mo</strong></td>`;
        
        downPayments.forEach(down => {
            const residualValue = msrp * (residualPct / 100);
            const netCap = sellingPrice - down;
            const depreciation = netCap - residualValue;
            const monthlyDepreciation = depreciation / term;
            const rentCharge = (netCap + residualValue) * mf;
            const monthlyTax = (monthlyDepreciation + rentCharge) * taxRate;
            const monthlyPayment = monthlyDepreciation + rentCharge + monthlyTax;
            
            const cellClass = monthlyPayment < 400 ? 'matrix-green' : 
                             monthlyPayment < 600 ? 'matrix-yellow' : 'matrix-red';
            
            html += `<td class="${cellClass}">$${monthlyPayment.toFixed(0)}</td>`;
        });
        
        html += '</tr>';
    });
    
    html += '</tbody></table>';
    
    document.getElementById('matrixOutput').innerHTML = html;
    document.getElementById('matrixSection').classList.remove('hidden');
}

// ============================================================================
// SECTION 16: PAIRWISE COMPARISON RENDERER
// ============================================================================

function renderPairwiseComparisons(cards) {
    const container = document.getElementById('pairwiseGrid');
    if (!container) return;
    
    container.innerHTML = "";
    if (cards.length < 2) return;

    for (let i = 0; i < cards.length; i++) {
        for (let j = i + 1; j < cards.length; j++) {
            const c1 = cards[i];
            const c2 = cards[j];
            
            const name1 = `${c1.querySelector('.year')?.value || ''} ${c1.querySelector('.model')?.value || ''}`.trim() || `Vehicle ${String.fromCharCode(65 + i)}`;
            const name2 = `${c2.querySelector('.year')?.value || ''} ${c2.querySelector('.model')?.value || ''}`.trim() || `Vehicle ${String.fromCharCode(65 + j)}`;
            
            const p1 = parseFloat(c1.dataset.monthlyPayment) || 0;
            const p2 = parseFloat(c2.dataset.monthlyPayment) || 0;
            const diffP = p1 - p2;
            
            const t1 = parseFloat(c1.dataset.totalCost) || 0;
            const t2 = parseFloat(c2.dataset.totalCost) || 0;
            const diffT = t1 - t2;
            
            const cardDiv = document.createElement('div');
            cardDiv.className = 'pairwise-card';
            cardDiv.innerHTML = `
                <div class="pairwise-header">${name1} vs ${name2}</div>
                <div class="diff-row">
                    <span>Monthly:</span>
                    <span class="${diffP < 0 ? 'diff-green' : 'diff-red'}">
                        ${diffP < 0 ? '✓ ' + name1 + ' is $' + Math.abs(diffP).toFixed(2) + ' less' : '✗ ' + name1 + ' is $' + diffP.toFixed(2) + ' more'}
                    </span>
                </div>
                <div class="diff-row">
                    <span>Total Cost:</span>
                    <span class="${diffT < 0 ? 'diff-green' : 'diff-red'}">
                        ${diffT < 0 ? '✓ ' + name1 + ' saves $' + Math.abs(diffT).toFixed(2) : '✗ ' + name1 + ' costs $' + diffT.toFixed(2) + ' more'}
                    </span>
                </div>
            `;
            container.appendChild(cardDiv);
        }
    }
    
    document.getElementById('pairwiseSection')?.classList.remove('hidden');
}

