// SECTION 17: SCENARIO ANALYSIS RUNNER
// ============================================================================

const SCENARIO_DB = [
    { id: 1, name: "Winter Weather Impact", tags: ["seasonal", "range"], description: "Analyzes cold weather impact on EV range and ICE efficiency" },
    { id: 2, name: "High Mileage Driver", tags: ["mileage", "depreciation"], description: "Evaluates cost impact for drivers exceeding 20k miles/year" },
    { id: 3, name: "Urban vs Highway", tags: ["usage", "efficiency"], description: "Compares city vs highway driving cost differences" }
];

function runScenarioAnalysis() {
    const id = parseInt(document.getElementById('scenarioSelect')?.value);
    if (!id) return;
    
    const scen = SCENARIO_DB.find(s => s.id === id);
    if (!scen) return;
    
    const cards = document.querySelectorAll('.vehicle-card');
    const resultsDiv = document.getElementById('scenarioResults');
    
    let html = `<table class="scenario-table"><thead><tr><th>Vehicle</th><th>Scenario Impact</th><th>Adjusted Metric</th></tr></thead><tbody>`;
    
    cards.forEach((card, i) => {
        const name = `${card.querySelector('.make')?.value || ''} ${card.querySelector('.model')?.value || ''}`.trim() || `Vehicle ${String.fromCharCode(65 + i)}`;
        let impact = "";
        let metric = "";
        
        if (scen.id === 1) {
            const isEV = (card.querySelector('.battery_capacity')?.value || 0) > 0;
            if (isEV) {
                impact = "❄️ Winter Range Loss (-30%)";
                metric = "Range: Reduced";
            } else {
                impact = "🛢️ ICE Cold Start Wear";
                metric = "Maint: +15%";
            }
        } else if (scen.id === 2) {
            const miles = parseFloat(card.querySelector('.annualMileage')?.value) || 12000;
            impact = miles < 20000 ? "⚠️ Penalty Risk" : "✅ High Miles";
            metric = "Depreciation: " + (miles < 20000 ? "Normal" : "High");
        } else {
            impact = "Standard Analysis";
            metric = "See Matrix";
        }
        
        html += `<tr><td>${name}</td><td>${impact}</td><td>${metric}</td></tr>`;
    });
    
    html += `</tbody></table>`;
    resultsDiv.innerHTML = html;
}

// Populate scenario dropdown
function populateScenarioDropdown() {
    const select = document.getElementById('scenarioSelect');
    if (!select) return;
    
    SCENARIO_DB.forEach(scen => {
        const option = document.createElement('option');
        option.value = scen.id;
        option.textContent = scen.name;
        select.appendChild(option);
    });
}

