    function copyVehicleData(source, target) {
        source.querySelectorAll('input, select').forEach((elem, idx) => {
            const targetElem = target.querySelectorAll('input, select')[idx];
            if (targetElem) {
                if (elem.type === 'checkbox') targetElem.checked = elem.checked;
                else targetElem.value = elem.value;
            }
        });
    }

    function renumberVehicles() {
        const cards = document.querySelectorAll('.vehicle-card');
        vehicleCount = cards.length;
        cards.forEach((card, idx) => {
            card.setAttribute('data-id', idx + 1);
            card.querySelector('.v-num').textContent = idx + 1;
        });
    }

    
    
    // ============================================================================
    // VALIDATION & LOGIC
    // ============================================================================
    function validateVin(vin) {
        if (vin.length !== 17) return false;
        if (/[IOQ]/.test(vin)) return false;
        let sum = 0;
        for (let i = 0; i < 17; i++) {
            const char = vin[i].toUpperCase();
            const value = isNaN(char) ? VIN_TRANS[char] : parseInt(char);
            if(value === undefined) return false;
            sum += value * VIN_WEIGHTS[i];
        }
        const checkDigit = vin[8];
        const calculatedDigit = sum % 11;
        const expected = (calculatedDigit === 10) ? 'X' : calculatedDigit.toString();
        return checkDigit.toUpperCase() === expected;
    }

    async function handleVinDecode(input) {
        const card = input.closest('.vehicle-card');
        const vin = input.value.trim().toUpperCase();
        if (vin.length !== 17) return;
        if (!validateVin(vin)) { showToast('Invalid VIN (check digit).', 'error'); return; }

        showLoading(card, true);
        const loadingDiv = input.parentElement.querySelector('.field-loading');
        if (loadingDiv) loadingDiv.textContent = 'Decoding VIN...';
        
        try {
            const res = await fetch(`https://vpic.nhtsa.dot.gov/api/vehicles/decodevinvalues/${vin}?format=json`);
            const data = await res.json();
            const row = data.Results?.[0];

            if (row && row.Make) {
                card.querySelector('.year').value = row.ModelYear;
                card.querySelector('.make').value = row.Make;
                card.querySelector('.model').value = row.Model;
                card.querySelector('.trim').value = row.Trim || row.Series;
                detectFuelType(card, row);
                populateFeeDefaults(card);
                populateResidual(card);

                await fetchMarketCheckData(card, vin); 

                if (loadingDiv) loadingDiv.textContent = 'Fetching EPA fuel economy...';
                try {
                    const year = card.querySelector('.year').value;
                    const make = card.querySelector('.make').value;
                    const model = card.querySelector('.model').value;
                    const epaData = await fetchEpaData(year, make, model);
                    if (epaData) {
                        applyEpaDataToCard(card, epaData);
                        showToast('VIN decoded with EPA data.');
                    } else {
                        showToast('VIN decoded, EPA data not found.');
                    }
                } catch(epaErr) {
                    console.warn("EPA fetch failed", epaErr);
                    showToast('VIN decoded, no EPA data.');
                }
            } else {
                showToast('VIN not found.', 'error');
            }
        } catch (error) {
            showToast('VIN decode failed.', 'error');
        } finally {
            showLoading(card, false);
            if (loadingDiv) loadingDiv.textContent = '';
        }
    }

    async function fetchEpaData(year, make, model) {
        try {
            const optionsUrl = `https://www.fueleconomy.gov/ws/rest/vehicle/menu/options?year=${year}&make=${encodeURIComponent(make)}&model=${encodeURIComponent(model)}`;
            const optionsRes = await fetch(optionsUrl);
            if (!optionsRes.ok) return null;
            const optionsText = await optionsRes.text();
            const parser = new DOMParser();
            const optionsDoc = parser.parseFromString(optionsText, "text/xml");
            
            const menuItem = optionsDoc.querySelector('menuItem');
            if (!menuItem) return null;
            const vehicleId = menuItem.querySelector('value')?.textContent;
            if (!vehicleId) return null;
            
            const vehicleUrl = `https://www.fueleconomy.gov/ws/rest/vehicle/${vehicleId}`;
            const vehicleRes = await fetch(vehicleUrl);
            if (!vehicleRes.ok) return null;
            const vehicleText = await vehicleRes.text();
            const vehicleDoc = parser.parseFromString(vehicleText, "text/xml");
            
            const getText = (tag) => vehicleDoc.querySelector(tag)?.textContent || null;
            const getNum = (tag) => {
                const val = getText(tag);
                return val ? parseFloat(val) : null;
            }

            return {
                citympg: getNum('city08'), highwaympg: getNum('highway08'), combinedmpg: getNum('comb08'),
                citympge: getNum('cityA08'), highwaympge: getNum('highwayA08'), combinedmpge: getNum('combA08'),
                kwh100mi: getNum('kwhPer100') || getNum('kwhHundredMiles'),
                eparangemiles: getNum('range'), electricrangemiles: getNum('rangeElectric'),
                annualfuelcost: getNum('fuelCost08'), fueltype: getText('fuelType'), fueltype1: getText('fuelType1')
            };

        } catch (err) {
            console.error("EPA API error:", err);
            return null;
        }
    }

    function applyEpaDataToCard(card, epa) {
        if (!epa) return;
        const fuelType = card.querySelector('.fuelType').value;
        
        if (epa.citympg) card.querySelector('.epaCityMpg').value = epa.citympg;
        if (epa.highwaympg) card.querySelector('.epaHwyMpg').value = epa.highwaympg;
        if (epa.combinedmpg) card.querySelector('.epaCombinedMpg').value = epa.combinedmpg;
        
        if (fuelType === 'ev' || fuelType === 'phev') {
            if (epa.citympge) {
                if(fuelType === 'ev') card.querySelector('.mpgeCity').value = epa.citympge;
                else card.querySelector('.mpgeCityPhev').value = epa.citympge;
            }
            if (epa.highwaympge) {
                if(fuelType === 'ev') card.querySelector('.mpgeHwy').value = epa.highwaympge;
                else card.querySelector('.mpgeHwyPhev').value = epa.highwaympge;
            }
            if (epa.combinedmpge) {
                if(fuelType === 'ev') card.querySelector('.mpgeCombined').value = epa.combinedmpge;
                else card.querySelector('.mpgeCombinedPhev').value = epa.combinedmpge;
            }
        }
        
        if (epa.electricrangemiles) {
            const evRange = card.querySelector('.rangeElectric');
            card.querySelector('.rangePhevEv').value = epa.electricrangemiles;
            if (evRange) evRange.value = epa.electricrangemiles;
        }
        if (epa.eparangemiles && fuelType === 'gas') {
            const gasRange = card.querySelector('.rangePhevGas');
            if (gasRange) gasRange.value = epa.eparangemiles;
        }
        
        if (epa.kwh100mi && card.querySelector('.kwhPer100Mi')) {
            card.querySelector('.kwhPer100Mi').value = epa.kwh100mi.toFixed(2);
        }

        calculateFuelCosts(card.querySelector('.fuelType'));
    }

    function detectFuelType(card, vinData) {
        const fuel = vinData.FuelTypePrimary || '';
        const select = card.querySelector('.fuelType');
        if (fuel.includes('Electric') && !fuel.includes('Gasoline')) {
            select.value = 'ev';
        } else if (fuel.includes('Plug-in') || fuel.includes('PHEV')) {
            select.value = 'phev';
        } else {
            select.value = 'gas';
        }
        handleFuelTypeChange(select);
    }
    
    async function fetchMarketCheckData(card, vin) {
        try {
            const apiKey = API_KEYS.getNextApiKey();
            const url = `https://marketcheck-prod.apigee.net/v2/search/car/active?api_key=${apiKey}&vin=${encodeURIComponent(vin)}`;
            const res = await fetch(url);
            if (!res.ok) return;
            const data = await res.json();
            const listing = data.listings?.[0];
            if (listing) {
                if (listing.price) {
                    card.querySelector('.listingPrice').value = listing.price;
                    card.querySelector('.capitalizedAmount').value = listing.price;
                }
                if (listing.msrp) card.querySelector('.msrp').value = listing.msrp;

                if (listing.dealer_name) {
                    card.querySelector('.dealerName').value = listing.dealer_name;
                    card.querySelector('.dealer-badge').classList.remove('hidden');
                }
                if (listing.dealer_phone) {
                    card.querySelector('.dealerPhone').value = listing.dealer_phone;
                }

                const locParts = [];
                if (listing.dealer_city) locParts.push(listing.dealer_city);
                if (listing.dealer_state) locParts.push(listing.dealer_state);
                if (listing.dealer_zip) locParts.push(listing.dealer_zip);
                if (locParts.length > 0) {
                    card.querySelector('.dealerLocation').value = locParts.join(', ');
                }

                if (listing.stock_no) card.querySelector('.stockNumber').value = listing.stock_no;
                if (listing.miles) card.querySelector('.listingMiles').value = listing.miles;
                if (listing.exterior_color) card.querySelector('.exteriorColor').value = listing.exterior_color;
                if (listing.interior_color) card.querySelector('.interiorColor').value = listing.interior_color;
                if (listing.dom) card.querySelector('.daysOnMarket').value = listing.dom;

                let source = 'MarketCheck';
                if (listing.source) {
                    source = listing.source;
                    if (source.toLowerCase().includes('neovin')) {
                        card.querySelector('.neovin-badge').classList.remove('hidden');
                        card.querySelector('.listingSource').value = 'NeoVIN';
                    } else {
                        card.querySelector('.listingSource').value = source;
                    }
                }

                if (listing.dealer_discount) {
                    const discount = Math.round(listing.dealer_discount);
                    card.querySelector('.leaseIncentives').value = discount;
                    card.querySelector('.financeIncentives').value = discount;
                }
                if (listing.incentives && !listing.dealer_discount) {
                    const incentives = Math.round(listing.incentives);
                    card.querySelector('.leaseIncentives').value = incentives;
                    card.querySelector('.financeIncentives').value = incentives;
                }

                showToast('MarketCheck data loaded successfully');
                calculateCapitalizedAmount(card);
            }
        } catch (error) {
            console.warn('MarketCheck fetch failed:', error);
        }
    }

    function handleZipLookup(input) {
        const card = input.closest('.vehicle-card');
        const zip = input.value.substring(0, 5);
        if (zip.length < 3) return;
        const prefix = zip.substring(0, 3);
        const state = ZIP_TO_STATE[prefix] || 'UNK';
        const taxRate = STATE_TAX[state] || 6.0;
        card.querySelector('.state').value = state;
        card.querySelector('.taxRate').value = taxRate;
        populateStateFees(card, state);
    }

    // ============================================================================
    // CALCULATIONS & HELPER FUNCTIONS
    // ============================================================================

    function getCardData(card) {
        const getVal = (sel, type = 'string') => {
            const el = card.querySelector(sel);
            if (!el) return (type === 'number' ? 0 : (type === 'boolean' ? false : ''));
            if (type === 'number') return parseFloat(el.value) || 0;
            if (type === 'boolean') return el.checked;
            return el.value;
        };
        const upfrontFees = ['acqFee','docFee','regFee','titleFee','plateFee','otherFees']
            .reduce((total, fee) => total + (getVal(`.${fee.replace('Fee','Check')}`,'boolean') ? 0 : getVal(`.${fee}`,'number')), 0);
        const capFees = ['acqFee','docFee','regFee','titleFee','plateFee','otherFees']
            .reduce((total, fee) => total + (getVal(`.${fee.replace('Fee','Check')}`,'boolean') ? getVal(`.${fee}`,'number') : 0), 0);
        
        const totalFees = upfrontFees + capFees;

        return {
            id: card.dataset.id,
            vin: getVal('.vin'), zip: getVal('.zip'), year: getVal('.year'), make: getVal('.make'), model: getVal('.model'), trim: getVal('.trim'),
            state: getVal('.state'), taxRate: getVal('.taxRate', 'number') / 100, fuelType: getVal('.fuelType'), epaCityMpg: getVal('.epaCityMpg','number'), epaHwyMpg: getVal('.epaHwyMpg','number'),
            msrp: getVal('.msrp', 'number'), listingPrice: getVal('.listingPrice', 'number'), capitalizedAmount: getVal('.capitalizedAmount', 'number'),
            leaseIncentives: getVal('.leaseIncentives', 'number'), financeIncentives: getVal('.financeIncentives', 'number'), stateCredit: getVal('.stateCredit', 'number'),
            residualPct: getVal('.residualPct', 'number') / 100, moneyFactor: getVal('.moneyFactor', 'number'), apr: getVal('.apr', 'number'),
            msdActive: getVal('.msdActive', 'boolean'), msdCount: getVal('.msdCount', 'number'), zeroDriveOff: getVal('.zeroDriveOff', 'boolean'),
            leaseTerm: getVal('.leaseTerm', 'number'), annualMileage: getVal('.annualMileage', 'number'),
            condition: getVal('.condition'), dealType: getVal('.dealType'), dealArrangement: getVal('.dealArrangement'),
            downPayment: getVal('.downPayment', 'number'), downScenario: getVal('.downScenario'),
            tradeAllowance: getVal('.tradeAllowance', 'number'), payoffAmount: getVal('.payoffAmount', 'number'), tradeEquity: getVal('.tradeEquity', 'number'), tradeScenario: getVal('.tradeScenario'), checkBackAmount: getVal('.checkBackAmount', 'number'),
            taxMethod: getVal('.taxMethod'), upfrontFees, capFees, totalFees,
            balloonAmount: getVal('.balloonAmount', 'number'), balloonPct: getVal('.balloonPct', 'number') / 100,
            origMsrp: getVal('.origMsrp', 'number')
        };
    }

    
    
    

    

    // --- UI & DOM ---
    function renderBreakdown(card, calcs, sectionClass) {
        card.querySelectorAll(`${sectionClass} [data-field]`).forEach(el => {
            const key = el.dataset.field;
            if (calcs[key] !== null && calcs[key] !== undefined) {
                if (['msrpToCap', 'msrpToRes', 'capToRes', 'origMsrpToRes'].includes(key)) {
                    el.textContent = (calcs[key] * 100).toFixed(1) + '%';
                } else if (key === 'mfDisplay') {
                    el.textContent = calcs[key];
                } else {
                    el.textContent = formatCurrency(calcs[key]);
                }
            } else {
                el.textContent = '--';
            }
        });
        card.querySelector('.breakdown-section').classList.toggle('hidden', sectionClass !== '.breakdown-section');
        card.querySelector('.finance-breakdown-section').classList.toggle('hidden', sectionClass !== '.finance-breakdown-section');
    }

    function renderComparisonTables(results) {
        renderLeaseOnlyTable(results);
        renderLeaseVsFinanceTable(results);
        renderAllMetricsTable(results);
    }
    
    function renderLeaseOnlyTable(results) {
        const table = document.getElementById('comparisonTableLease');
        let html = '<thead><tr><th>Metric</th>';
        results.forEach(r => { html += `<th>${r.make} ${r.model} (#${r.id})</th>`; });
        html += '</tr></thead><tbody>';

        const rows = [
            { label: 'Monthly Payment', key: 'totalMonthly', fmt: 'money', better: 'lower' },
            { label: 'Due at Signing', key: 'dueAtSigning', fmt: 'money', better: 'lower' },
            { label: 'Total Cost', key: 'totalCost', fmt: 'money', better: 'lower' },
            { label: 'Buyout', key: 'buyout', fmt: 'money', better: 'lower' },
            { label: 'Cost Per Mile', key: 'costPerMile', fmt: 'money', better: 'lower' }
        ];

        rows.forEach(row => {
            html += `<tr><td>${row.label}</td>`;
            // Calculate best value only for valid lease results
            const validResults = results.filter(r => r.lease);
            const values = validResults.map(r => r.lease[row.key]);
            const best = values.length > 0 ? ((row.better === 'lower') ? Math.min(...values) : Math.max(...values)) : null;
            
            results.forEach(r => {
                if(!r.lease) { html += `<td>N/A</td>`; return; }
                const val = r.lease[row.key];
                const isBest = (val === best) ? 'better' : '';
                html += `<td class="${isBest}">${formatCurrency(val)}</td>`;
            });
            html += '</tr>';
        });

        html += '</tbody>';
        table.innerHTML = html;
    }

    function renderLeaseVsFinanceTable(results) {
         const table = document.getElementById('comparisonTableVs');
         let html = '<thead><tr><th>Vehicle</th><th>Lease Monthly</th><th>Finance Monthly</th><th>Lease Total Cost</th><th>Finance Total Cost</th></tr></thead><tbody>';
         results.forEach(r => {
             if (r.lease && r.finance) {
                 const lCost = r.lease.totalCost;
                 const fCost = r.finance.finTotalCost;
                 const lBetter = lCost < fCost ? 'better' : '';
                 const fBetter = fCost < lCost ? 'better' : '';
                 html += `<tr>
                    <td>${r.make} ${r.model} (#${r.id})</td>
                    <td>${formatCurrency(r.lease.totalMonthly)}</td>
                    <td>${formatCurrency(r.finance.finMonthly)}</td>
                    <td class="${lBetter}">${formatCurrency(lCost)}</td>
                    <td class="${fBetter}">${formatCurrency(fCost)}</td>
                 </tr>`;
             }
         });
         html += '</tbody>';
         table.innerHTML = html;
    }

    function renderAllMetricsTable(results) {
        // Placeholder implementation
        const table = document.getElementById('comparisonTableAll');
        table.innerHTML = '<thead><tr><th>Info</th></tr></thead><tbody><tr><td>Detailed metrics table logic here...</td></tr></tbody>';
    }
    
    // --- HELPERS & UI HANDLERS ---
    
    
    function calculateCombinedMpg(input) {
        const card = input.closest('.vehicle-card');
        const city = parseFloat(card.querySelector('.epaCityMpg').value) || 0;
        const hwy = parseFloat(card.querySelector('.epaHwyMpg').value) || 0;
        if (city > 0 && hwy > 0) {
            card.querySelector('.epaCombinedMpg').value = ((city * 0.55) + (hwy * 0.45)).toFixed(1);
        }
    }
    
    function calculateCombinedMpge(input, type) {
        const card = input.closest('.vehicle-card');
        const prefix = (type === 'phev') ? 'Phev' : '';
        const city = parseFloat(card.querySelector(`.mpgeCity${prefix}`).value) || 0;
        const hwy = parseFloat(card.querySelector(`.mpgeHwy${prefix}`).value) || 0;
        if (city > 0 && hwy > 0) {
            card.querySelector(`.mpgeCombined${prefix}`).value = ((city * 0.55) + (hwy * 0.45)).toFixed(1);
        }
    }

    function calculatePhevRange(input) {
        const card = input.closest('.vehicle-card');
        const evRange = parseFloat(card.querySelector('.rangePhevEv').value) || 0;
        const gasRange = parseFloat(card.querySelector('.rangePhevGas').value) || 0;
        card.querySelector('.rangePhevCombined').value = evRange + gasRange;
    }
    
    
    
    function populateFeeDefaults(card) {
        const make = card.querySelector('.make').value;
        const fees = FEES_BY_MAKE[make] || FEES_BY_MAKE['DEFAULT'];
        card.querySelector('.acqFee').value = fees.acquisition;
    }

    function populateStateFees(card, state) {
        const fees = STATE_VEHICLE_FEES[state] || STATE_VEHICLE_FEES['DEFAULT'];
        card.querySelector('.regFee').value = fees.registration;
        card.querySelector('.titleFee').value = fees.title;
        card.querySelector('.plateFee').value = fees.plate;
    }

    function populateResidual(card) {
        const make = card.querySelector('.make').value;
        const term = card.querySelector('.leaseTerm').value;
        const mileage = card.querySelector('.annualMileage').value;
        const condition = card.querySelector('.condition').value;

        const resMatrix = RESIDUAL_MATRIX[condition] || RESIDUAL_MATRIX['new'];
        const makeMatrix = resMatrix[make] || resMatrix['DEFAULT'];
        // Try simplified lookup for matrix structure used
        const res = (makeMatrix[term] && makeMatrix[term][mileage]) ? makeMatrix[term][mileage] : 50; 
        
        card.querySelector('.residualPct').value = res;
    }
    
    function calculateTradeEquity(input) {
        const card = input.closest('.vehicle-card');
        const allowance = parseFloat(card.querySelector('.tradeAllowance').value) || 0;
        const payoff = parseFloat(card.querySelector('.payoffAmount').value) || 0;
        card.querySelector('.tradeEquity').value = (allowance - payoff).toFixed(2);
    }

    function calculateCapitalizedAmount(card) {
        const listing = parseFloat(card.querySelector('.listingPrice').value) || 0;
        const incentives = parseFloat(card.querySelector('.leaseIncentives').value) || 0;
        const stateCredit = parseFloat(card.querySelector('.stateCredit').value) || 0;
        
        let capFees = 0;
        card.querySelectorAll('.fee-cap-check input:checked').forEach(chk => {
            const feeInput = chk.closest('.fee-cap-row').querySelector('input[type="number"]');
            capFees += parseFloat(feeInput.value) || 0;
        });

        let capRedux = 0;
        const down = parseFloat(card.querySelector('.downPayment').value) || 0;
        const equity = parseFloat(card.querySelector('.tradeEquity').value) || 0;
        const checkBack = parseFloat(card.querySelector('.checkBackAmount').value) || 0;
        
        const downScen = card.querySelector('.downScenario').value;
        const tradeScen = card.querySelector('.tradeScenario').value;

        if (downScen === 'cap_reduction') capRedux += down;
        else if (downScen === 'split_50_50') capRedux += (down / 2);

        if (tradeScen === 'cap_reduction') capRedux += equity;
        else if (tradeScen === 'split_50_50') capRedux += (equity / 2);
        else if (tradeScen === 'check_back') capRedux += (equity - checkBack);

        card.querySelector('.capitalizedAmount').value = (listing - incentives - stateCredit + capFees - capRedux).toFixed(2);
    }

    function handleDealTypeChange(select) {
        const card = select.closest('.vehicle-card');
        const type = select.value;
        card.querySelector('.finance-breakdown-section').classList.toggle('hidden', !type.includes('finance'));
        card.querySelector('.breakdown-section').classList.toggle('hidden', type.includes('finance'));
        card.querySelectorAll('.balloon-fields').forEach(f => f.classList.toggle('hidden', !type.includes('balloon')));
    }

    function handleArrangementChange(select) {
        // Placeholder for single pay logic UI updates
    }
    
    function handleTradeScenarioChange(select) {
        const card = select.closest('.vehicle-card');
        card.querySelector('.check-back-field').classList.toggle('hidden', select.value !== 'check_back');
    }

    function handleMsdToggle(checkbox) {
        const card = checkbox.closest('.vehicle-card');
        card.querySelector('.msd-field').classList.toggle('hidden', !checkbox.checked);
    }
    
    function handleConditionChange(select) {
        const card = select.closest('.vehicle-card');
        const cond = select.value;
        card.querySelectorAll('.orig-msrp-row, .orig-msrp-breakdown').forEach(el => {
             el.classList.toggle('hidden', cond === 'new');
        });
        populateResidual(card);
    }

    function syncMfApr(input, type) {
        const card = input.closest('.vehicle-card');
        if (type === 'mf') {
            card.querySelector('.apr').value = (parseFloat(input.value) * 2400).toFixed(2);
        } else {
            card.querySelector('.moneyFactor').value = (parseFloat(input.value) / 2400).toFixed(6);
        }
    }

    function syncBalloonFields(input, type) {
        const card = input.closest('.vehicle-card');
        const msrp = parseFloat(card.querySelector('.msrp').value) || 0;
        if (msrp === 0) return;
        if (type === 'amount') {
            card.querySelector('.balloonPct').value = ((parseFloat(input.value) / msrp) * 100).toFixed(1);
        } else {
            card.querySelector('.balloonAmount').value = (msrp * (parseFloat(input.value) / 100)).toFixed(0);
        }
    }
    
    function showLoading(card, isLoading) {
        card.classList.toggle('loading', isLoading);
    }

    
    
    
    
    function formatCurrency(val) {
        if(typeof val !== 'number' || !isFinite(val)) return '--';
        return val.toLocaleString('en-US', {style: 'currency', currency: 'USD'});
    }
    
