// VIN DECODER (MarketCheck Primary with Key Rotation + NHTSA Fallback)
window.decodeVIN = async function(vinInput, card) {
  const vin = vinInput.value.trim().toUpperCase();
  if (vin.length !== 17) {
    vinInput.parentElement.querySelector('.field-error').textContent = 'Invalid VIN (17 chars required)';
    return;
  }
  
  const loader = vinInput.parentElement.querySelector('.field-loading');
  const errorEl = vinInput.parentElement.querySelector('.field-error');
  loader.textContent = 'Decoding...';
  errorEl.textContent = '';
  
  // Try MarketCheck with key rotation
  let mcData = null;
  let attempts = 0;
  const maxAttempts = API_KEYS.marketcheck.length;
  
  while (attempts < maxAttempts && !mcData) {
    try {
      const apiKey = getNextApiKey();
      loader.textContent = `Decoding (MarketCheck ${attempts + 1}/${maxAttempts})...`;
      
      const mcResponse = await fetch(
        `https://mc-api.marketcheck.com/v2/decode/car/${vin}?api_key=${apiKey}`
      );
      
      // Check rate limit headers
      const rateLimitRemaining = mcResponse.headers.get('RateLimit-Remaining');
      const quotaRemaining = mcResponse.headers.get('Quota-Remaining');
      
      if (mcResponse.status === 429) {
        // Rate limit exceeded - try next key
        console.warn(`Rate limit exceeded for key ${attempts + 1}, trying next key...`);
        const retryAfter = mcResponse.headers.get('Retry-After');
        if (retryAfter) {
          console.log(`Retry after: ${retryAfter} seconds`);
        }
        attempts++;
        continue;
      }
      
      if (!mcResponse.ok) {
        throw new Error(`MarketCheck error: ${mcResponse.status}`);
      }
      
      mcData = await mcResponse.json();
      
      // Log remaining quota for monitoring
      if (quotaRemaining !== null) {
        console.log(`MarketCheck quota remaining: ${quotaRemaining}`);
      }
      
      break; // Success - exit loop
      
    } catch (error) {
      console.warn(`MarketCheck attempt ${attempts + 1} failed:`, error);
      attempts++;
      
      if (attempts >= maxAttempts) {
        // All keys failed - fall back to NHTSA
        console.warn('All MarketCheck keys failed, using NHTSA fallback');
        return await decodeVINwithNHTSA(vin, card, loader, errorEl);
      }
    }
  }
  
  // If we got MarketCheck data, process it
  if (mcData) {
    try {
      const mc = mcData.build || mcData;
      
      // Populate primary fields from MarketCheck
      if (mc.year) card.querySelector('.year').value = mc.year;
      if (mc.make) card.querySelector('.make').value = mc.make;
      if (mc.model) card.querySelector('.model').value = mc.model;
      if (mc.trim) card.querySelector('.trim').value = mc.trim;
      
      // MarketCheck-specific fields
      if (mc.msrp) card.querySelector('.msrp').value = mc.msrp;
      if (mc.exterior_color) card.querySelector('.exteriorColor').value = mc.exterior_color;
      if (mc.interior_color) card.querySelector('.interiorColor').value = mc.interior_color;
      if (mc.drivetrain) card.querySelector('.drivetrain').value = mc.drivetrain;
      if (mc.transmission) card.querySelector('.transmission').value = mc.transmission;
      if (mc.engine) card.querySelector('.engine').value = mc.engine;
      if (mc.body_type) card.querySelector('.bodyStyle').value = mc.body_type;
      
      // Fuel type detection
      if (mc.fuel_type) {
        const fuelType = mc.fuel_type.toLowerCase();
        if (fuelType.includes('electric') || fuelType.includes('bev')) {
          card.querySelector('.fuelType').value = 'ev';
        } else if (fuelType.includes('hybrid') || fuelType.includes('phev')) {
          card.querySelector('.fuelType').value = 'phev';
        } else {
          card.querySelector('.fuelType').value = 'gas';
        }
      }
      
      // EPA ratings from MarketCheck
      if (mc.city_mpg) card.querySelector('.epaCityMpg').value = mc.city_mpg;
      if (mc.highway_mpg) card.querySelector('.epaHighwayMpg').value = mc.highway_mpg;
      if (mc.mpg) card.querySelector('.epaCombinedMpg').value = mc.mpg;
      
      // Supplement with NHTSA for missing fields
      const needsNHTSA = !mc.trim || !mc.exterior_color || !mc.body_type;
      
      if (needsNHTSA) {
        loader.textContent = 'Supplementing (NHTSA)...';
        await supplementWithNHTSA(vin, card, mc);
      }
      
      loader.textContent = '✓ Decoded';
      window.toggleFuelFields(card);
      
    } catch (error) {
      console.error('Error processing MarketCheck data:', error);
      return await decodeVINwithNHTSA(vin, card, loader, errorEl);
    }
  }
};

// ZIP CODE LOOKUP (Zippopotam API)
window.lookupZIP = function(zipInput, card) {
  const zip = zipInput.value.trim();
  if (zip.length !== 5) {
    zipInput.parentElement.querySelector('.field-error').textContent = 'Invalid ZIP (5 digits required)';
    return;
  }
  
  fetch(`https://api.zippopotam.us/us/${zip}`)
    .then(r => r.json())
    .then(data => {
      if (data.places && data.places.length > 0) {
        const place = data.places[0];
        card.querySelector('.city').value = place['place name'] || '';
        card.querySelector('.county').value = place['county'] || '';
        card.querySelector('.state').value = data.country.abbreviation || '';
        
        // Auto-populate tax rate and fees require STATES and STATE_VEHICLE_FEES defined globally
        if (typeof STATES !== 'undefined') {
            const stateCode = data.country.abbreviation;
            const stateTax = STATES.find(s => s.code === stateCode);
            if (stateTax) card.querySelector('.taxRate').value = (stateTax.tax * 100).toFixed(3);
        }
        
        if (typeof STATE_VEHICLE_FEES !== 'undefined') {
            const stateCode = data.country.abbreviation;
            const fees = STATE_VEHICLE_FEES[stateCode];
            if (fees) {
              card.querySelector('.acqFee').value = fees.acq;
              card.querySelector('.docFee').value = fees.doc;
              card.querySelector('.regFee').value = fees.reg;
              card.querySelector('.titleFee').value = fees.title;
              card.querySelector('.plateFee').value = fees.plate;
            }
        }
      }
    })
    .catch(e => console.error(e));
};

// FUEL TYPE FIELD VISIBILITY
window.toggleFuelFields = function(card) {
  const fuelType = card.querySelector('.fuelType').value;
  
  // Hide all fuel fields
  card.querySelectorAll('.gas-field, .ev-field, .phev-field').forEach(el => {
    el.classList.add('hidden');
  });
  
  // Show relevant fields
  if (fuelType === 'gas') {
    card.querySelectorAll('.gas-field').forEach(el => el.classList.remove('hidden'));
  } else if (fuelType === 'ev') {
    card.querySelectorAll('.ev-field').forEach(el => el.classList.remove('hidden'));
    card.querySelectorAll('.ev-surcharge-row, .mf-discount-row').forEach(el => el.classList.remove('hidden'));
  } else if (fuelType === 'phev') {
    card.querySelectorAll('.phev-field, .gas-field, .ev-field').forEach(el => el.classList.remove('hidden'));
  }
};

