function getResidual(term, mileage, condition = 'new') {
    const matrix = RESIDUAL_MATRIX[condition] || RESIDUAL_MATRIX.new;
    const termStr = term.toString();
    const mileageStr = mileage.toString();
    
    if (matrix.DEFAULT && matrix.DEFAULT[termStr] && matrix.DEFAULT[termStr][mileageStr]) {
        return matrix.DEFAULT[termStr][mileageStr] / 100;
    }
    return 0.50;
}

