function getResidualPercentage(brand, term, mileage, condition = "new") {
    if (!brand || !term || !mileage) return null;
    
    // Ensure RESIDUAL_MATRIX exists (loaded from the other file)
    if (typeof RESIDUAL_MATRIX === 'undefined') {
        console.error("CRITICAL: residual_matrix.js not loaded!");
        return 50; 
    }

    const termKey = String(term);
    const mileageKey = String(mileage);

    try {
        if (RESIDUAL_MATRIX[condition] &&
            RESIDUAL_MATRIX[condition][brand] &&
            RESIDUAL_MATRIX[condition][brand][termKey] &&
            RESIDUAL_MATRIX[condition][brand][termKey][mileageKey]) {
            return RESIDUAL_MATRIX[condition][brand][termKey][mileageKey];
        }
    } catch (e) {
        console.warn("Lookup failed for", brand, term, mileage);
    }
    return 50; // Fallback
}

